    // ---------------------------------------------------------------------------
    // Service dual-stack ipFamilyPolicy/ipFamilies validation regression tests
    //
    // u7s's ServiceIpAllocator only ever allocates from a single IPv4 CIDR — there
    // is no second allocator for any other family. Before this fix, a Service
    // claiming ipFamilyPolicy: RequireDualStack (or explicitly listing a
    // non-IPv4 family) was accepted and echoed back verbatim while only ever
    // getting one IPv4 ClusterIP allocated, silently breaking dual-stack routing
    // for any consumer (kube-proxy, DNS) that trusts the advertised policy. If
    // validate_service_ip_family_fields is removed or its call sites dropped,
    // these tests fail.
    // ---------------------------------------------------------------------------

    /// Creating a Service with ipFamilyPolicy: RequireDualStack on a cluster that
    /// only has an IPv4 allocator must be rejected with 422, not silently stored
    /// with a single allocated IPv4 ClusterIP.
    ///
    /// Also asserts the rejected attempt does not leak an IP from the pool: a
    /// second, plain Service created afterward must still receive the very first
    /// allocatable address, proving the earlier failed create never touched the
    /// allocator.
    #[tokio::test]
    async fn create_service_rejects_require_dual_stack_policy() {
        use axum::extract::{Path, State};
        use axum::response::IntoResponse;
        use std::net::Ipv4Addr;

        // Small CIDR so the first-allocatable address (offset 2) is deterministic.
        let state = make_state_with_cidr_for_resource_tests("10.0.0.0/29");

        let dual_stack_svc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "dual-svc", "namespace": "default" },
            "spec": {
                "type": "ClusterIP",
                "ipFamilyPolicy": "RequireDualStack",
                "ports": [{ "port": 80 }]
            }
        });
        let result = create_namespaced_resource(
            State(state.clone()),
            Path(("".into(), "v1".into(), "default".into(), "services".into())),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&dual_stack_svc).unwrap()),
        )
        .await;

        match result {
            Err(err) => assert_eq!(
                err.0,
                axum::http::StatusCode::UNPROCESSABLE_ENTITY,
                "RequireDualStack on a single-IPv4-family cluster must return 422 — \
                 accepting it stores a Service that claims dual-stack routing while \
                 only ever getting one allocated ClusterIP"
            ),
            Ok(_) => panic!(
                "Service with ipFamilyPolicy: RequireDualStack must be rejected — this \
                 cluster has no second-family allocator to actually satisfy it"
            ),
        }

        // The rejected create must not have consumed an IP: a plain Service created
        // next should get the first allocatable address in the range.
        let plain_svc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "plain-svc", "namespace": "default" },
            "spec": { "type": "ClusterIP", "ports": [{ "port": 80 }] }
        });
        let resp = create_namespaced_resource(
            State(state),
            Path(("".into(), "v1".into(), "default".into(), "services".into())),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&plain_svc).unwrap()),
        )
        .await
        .unwrap_or_else(|e| panic!("plain Service create must succeed: {e:?}"))
        .into_response();

        let body = axum::body::to_bytes(resp.into_body(), usize::MAX)
            .await
            .unwrap();
        let v: serde_json::Value = serde_json::from_slice(&body).unwrap();
        let cluster_ip = v["spec"]["clusterIP"].as_str().unwrap_or("").to_string();
        assert_eq!(
            cluster_ip,
            Ipv4Addr::new(10, 0, 0, 2).to_string(),
            "the rejected RequireDualStack create must not have leaked the first \
             allocatable IP (10.0.0.2) from the pool — got {cluster_ip}"
        );
    }

    /// Creating a Service with an explicit ipFamilies entry the cluster cannot
    /// allocate (IPv6) must be rejected with 422, regardless of ipFamilyPolicy.
    ///
    /// This is the exact shape reported live: ipFamilyPolicy: PreferDualStack with
    /// ipFamilies: [IPv4, IPv6] was accepted and echoed back verbatim while only a
    /// single IPv4 ClusterIP was ever allocated for it.
    #[tokio::test]
    async fn create_service_rejects_explicit_ipv6_family() {
        use axum::extract::{Path, State};

        let state = make_state_with_cidr_for_resource_tests("10.0.0.0/29");

        let svc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "prefer-dual-svc", "namespace": "default" },
            "spec": {
                "type": "ClusterIP",
                "ipFamilyPolicy": "PreferDualStack",
                "ipFamilies": ["IPv4", "IPv6"],
                "ports": [{ "port": 80 }]
            }
        });
        let result = create_namespaced_resource(
            State(state),
            Path(("".into(), "v1".into(), "default".into(), "services".into())),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&svc).unwrap()),
        )
        .await;

        match result {
            Err(err) => assert_eq!(
                err.0,
                axum::http::StatusCode::UNPROCESSABLE_ENTITY,
                "ipFamilies: [IPv4, IPv6] on a single-IPv4-family cluster must return 422 \
                 — accepting it stores a Service that advertises IPv6 support it can never \
                 actually allocate"
            ),
            Ok(_) => panic!(
                "Service explicitly requesting IPv6 in spec.ipFamilies must be rejected — \
                 this cluster has no IPv6 allocator to satisfy it"
            ),
        }
    }

    fn proto_headers() -> axum::http::HeaderMap {
        let mut h = axum::http::HeaderMap::new();
        h.insert(
            axum::http::header::CONTENT_TYPE,
            axum::http::HeaderValue::from_static("application/vnd.kubernetes.protobuf"),
        );
        h
    }

    /// publishNotReadyAddresses must survive a real protobuf-encoded Service create through
    /// the actual handler — not just the decoder in isolation.
    ///
    /// client-go's typed Service clientset defaults to protobuf content-type. This is the
    /// field a StatefulSet's headless Service relies on for peer discovery: the
    /// Endpoints/EndpointSlice controllers read it to decide whether to publish SRV DNS
    /// records for not-yet-ready pods. Before decode_service_proto_gen read this field, every
    /// such Service created via the typed clientset would silently lose it, breaking peer
    /// discovery for any StatefulSet pod still starting up.
    #[tokio::test]
    async fn service_create_via_protobuf_preserves_publish_not_ready_addresses() {
        use axum::body::to_bytes;
        use axum::extract::{Path, State};
        use axum::response::IntoResponse;
        use prost::Message;

        let state = make_state();

        let svc = crate::apps_gen::k8s::io::api::core::v1::Service {
            metadata: Some(
                crate::apps_gen::k8s::io::apimachinery::pkg::apis::meta::v1::ObjectMeta {
                    name: Some("headless-peer-discovery".to_string()),
                    namespace: Some("default".to_string()),
                    ..Default::default()
                },
            ),
            spec: Some(crate::apps_gen::k8s::io::api::core::v1::ServiceSpec {
                cluster_ip: Some("None".to_string()),
                publish_not_ready_addresses: Some(true),
                ports: vec![crate::apps_gen::k8s::io::api::core::v1::ServicePort {
                    port: Some(80),
                    ..Default::default()
                }],
                ..Default::default()
            }),
            status: None,
        };
        let mut raw = Vec::new();
        svc.encode(&mut raw).unwrap();

        let envelope = crate::apps_gen::k8s::io::apimachinery::pkg::runtime::Unknown {
            type_meta: Some(
                crate::apps_gen::k8s::io::apimachinery::pkg::runtime::TypeMeta {
                    api_version: Some("v1".to_string()),
                    kind: Some("Service".to_string()),
                },
            ),
            raw: Some(raw),
            ..Default::default()
        };
        let mut envelope_bytes = Vec::new();
        envelope.encode(&mut envelope_bytes).unwrap();

        let mut body = vec![0x6b, 0x38, 0x73, 0x00]; // k8s proto magic
        body.extend(envelope_bytes);

        let create_result = create_namespaced_resource(
            State(state.clone()),
            Path(("".into(), "v1".into(), "default".into(), "services".into())),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            proto_headers(),
            bytes::Bytes::from(body),
        )
        .await
        .unwrap_or_else(|_| panic!("protobuf-encoded Service create must succeed"))
        .into_response();
        assert_eq!(
            create_result.status(),
            axum::http::StatusCode::CREATED,
            "protobuf-encoded Service create must return 201"
        );

        let get_result = get_namespaced_resource(
            State(state.clone()),
            Path((
                "".into(),
                "v1".into(),
                "default".into(),
                "services".into(),
                "headless-peer-discovery".into(),
            )),
            axum::http::HeaderMap::new(),
        )
        .await
        .unwrap_or_else(|_| panic!("Service GET must succeed"));

        let body = to_bytes(get_result.into_body(), usize::MAX).await.unwrap();
        let v: serde_json::Value = serde_json::from_slice(&body).unwrap();

        assert_eq!(
            v["spec"]["publishNotReadyAddresses"], true,
            "publishNotReadyAddresses must survive a protobuf-encoded create — without it, a \
             StatefulSet headless Service's peer-discovery SRV records silently stop being \
             published for not-yet-ready pods"
        );
    }

    // -- delete_collection_namespaced_resource releases clusterIP sentinels --

    /// Deleting a Service collection must release the clusterIP sentinels so those
    /// IPs can be re-allocated.  Without this fix, each create-then-delete cycle
    /// leaks a sentinel, causing CIDR exhaustion on clusters that churn Services.
    #[tokio::test]
    async fn delete_collection_releases_cluster_ip_sentinels() {
        use crate::state::ServiceIpAllocator;
        use axum::extract::{Path, Query, State};
        use axum::response::IntoResponse;
        use std::sync::Arc;
        use u7s_store::SqliteStore;

        // /30 gives exactly one usable IP (.2); .1 is reserved for kubernetes service.
        // Use /29 so we have two usable IPs for two Services.
        let store = Arc::new(SqliteStore::new(":memory:").expect("in-memory store"));
        let alloc = ServiceIpAllocator::from_cidr("10.0.0.0/29").expect("valid CIDR");
        let state = crate::state::AppState::new_with_config(crate::state::AppStateConfig {
            store: store.clone(),
            sa_key: None,
            sa_decoding_key: None,
            token_map: std::collections::HashMap::new(),
            server_address: "https://localhost:6443".into(),
            cluster_ca_der: None,
            webhook_identity_pem: None,
            service_ip_allocator: Some(alloc),
            kubelet_client_identity_pem: None,
            kubelet_preferred_address: None,
            kubelet_port: 10250,
            continue_token_key: None,
            konnectivity_proxy_addr: None,
            sa_public_key_pem: None,
        });

        // Create two Services — allocation attaches a sentinel for each IP.
        for name in &["svc-a", "svc-b"] {
            let svc = serde_json::json!({
                "apiVersion": "v1",
                "kind": "Service",
                "metadata": { "name": name, "namespace": "default" },
                "spec": {}
            });
            let _ = create_namespaced_resource(
                State(state.clone()),
                Path(("".into(), "v1".into(), "default".into(), "services".into())),
                axum::extract::Query(CreateQuery::default()),
                test_user(),
                json_headers(),
                bytes::Bytes::from(serde_json::to_vec(&svc).unwrap()),
            )
            .await
            .unwrap_or_else(|_| panic!("Service create must succeed"))
            .into_response();
        }

        // Confirm two sentinels exist.
        let sentinel_prefix = crate::state::SERVICE_IP_PREFIX;
        let sentinels_before = store
            .list(sentinel_prefix, u7s_store::ListOptions::default())
            .await
            .expect("list sentinels");
        assert_eq!(
            sentinels_before.items.len(),
            2,
            "two Services must produce two clusterIP sentinels"
        );

        // Delete the entire services collection in the default namespace.
        delete_collection_namespaced_resource(
            State(state.clone()),
            Path(("".into(), "v1".into(), "default".into(), "services".into())),
            Query(CollectionQuery {
                watch: None,
                resource_version: None,
                label_selector: None,
                field_selector: None,
                limit: None,
                continue_token: None,
                send_initial_events: None,
                allow_watch_bookmarks: None,
                timeout_seconds: None,
            }),
            test_user(),
            HeaderMap::new(),
            Bytes::new(),
        )
        .await
        .unwrap_or_else(|_| panic!("delete_collection must succeed"));

        // Sentinels must be gone — without the fix they would remain and exhaust the CIDR.
        let sentinels_after = store
            .list(sentinel_prefix, u7s_store::ListOptions::default())
            .await
            .expect("list sentinels after delete");
        assert_eq!(
            sentinels_after.items.len(),
            0,
            "delete_collection must release clusterIP sentinels; \
             leaked sentinels cause CIDR exhaustion"
        );

        // Verify the CIDR can be fully allocated again (two IPs available).
        let ip1 = state
            .allocate_service_ip(false)
            .await
            .expect("allocation must not error")
            .expect("allocation must return Some after sentinels released");
        let ip2 = state
            .allocate_service_ip(false)
            .await
            .expect("allocation must not error")
            .expect("second allocation must return Some after sentinels released");
        assert_ne!(ip1, ip2, "reallocated IPs must be distinct");
    }

    // ---------------------------------------------------------------------------
    // ClusterIP auto-allocation regression tests
    //
    // These tests verify that POST /api/v1/namespaces/{ns}/services with an
    // allocator configured returns a Service with .spec.clusterIP populated.
    // If maybe_allocate_cluster_ip is removed or broken, all four tests fail.
    // ---------------------------------------------------------------------------

    fn make_state_with_cidr_for_resource_tests(
        cidr: &str,
    ) -> crate::state::AppState<u7s_store::SqliteStore> {
        use crate::state::{AppStateConfig, ServiceIpAllocator};
        use std::sync::Arc;
        use u7s_store::SqliteStore;

        let store = Arc::new(SqliteStore::new(":memory:").expect("in-memory store"));
        let alloc = ServiceIpAllocator::from_cidr(cidr).expect("valid CIDR");
        crate::state::AppState::new_with_config(AppStateConfig {
            store,
            sa_key: None,
            sa_decoding_key: None,
            token_map: std::collections::HashMap::new(),
            server_address: "https://localhost:6443".into(),
            cluster_ca_der: None,
            webhook_identity_pem: None,
            service_ip_allocator: Some(alloc),
            kubelet_client_identity_pem: None,
            kubelet_preferred_address: None,
            kubelet_port: 10250,
            continue_token_key: None,
            konnectivity_proxy_addr: None,
            sa_public_key_pem: None,
        })
    }

    /// POST of a ClusterIP Service must return a response with spec.clusterIP set to
    /// an address within the configured CIDR.
    ///
    /// Without maybe_allocate_cluster_ip, spec.clusterIP is never populated — the
    /// field comes back empty and DNS/kube-proxy cannot program service routing.
    #[tokio::test]
    async fn allocate_assigns_ip_from_cidr() {
        use axum::body::to_bytes;
        use axum::extract::{Path, State};
        use axum::response::IntoResponse;
        use std::net::Ipv4Addr;
        use std::str::FromStr;

        let state = make_state_with_cidr_for_resource_tests("10.96.0.0/12");

        let svc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "auto-ip-svc", "namespace": "default" },
            "spec": { "type": "ClusterIP", "ports": [{ "port": 80 }] }
        });

        let resp = create_namespaced_resource(
            State(state),
            Path(("".into(), "v1".into(), "default".into(), "services".into())),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&svc).unwrap()),
        )
        .await
        .unwrap_or_else(|e| panic!("Service create must succeed: {e:?}"))
        .into_response();

        assert_eq!(resp.status(), axum::http::StatusCode::CREATED);
        let body = to_bytes(resp.into_body(), usize::MAX).await.unwrap();
        let v: serde_json::Value = serde_json::from_slice(&body).unwrap();

        let cluster_ip = v["spec"]["clusterIP"].as_str().unwrap_or("").to_string();
        assert!(
            !cluster_ip.is_empty() && cluster_ip != "None",
            "spec.clusterIP must be populated after create — empty clusterIP breaks kube-proxy and DNS"
        );

        // Must be a valid IPv4 address within 10.96.0.0/12.
        let ip = Ipv4Addr::from_str(&cluster_ip).unwrap_or_else(|_| {
            panic!("spec.clusterIP must be a valid IPv4 address, got {cluster_ip}")
        });
        let base = u32::from(Ipv4Addr::new(10, 96, 0, 0));
        let mask: u32 = !((1u32 << (32 - 12)) - 1);
        assert_eq!(
            u32::from(ip) & mask,
            base & mask,
            "allocated clusterIP {ip} must be within 10.96.0.0/12"
        );
    }

    /// `POST ...?dryRun=All` for a ClusterIP Service with no explicit clusterIP must NOT
    /// reserve a real sentinel from the allocator.
    ///
    /// Before this fix, maybe_allocate_cluster_ip called `state.allocate_service_ip` (a real
    /// create-only store write) unconditionally, even under dryRun=All — the Service object
    /// itself correctly never persisted, but every dry-run create permanently burned one IP
    /// from the pool, since nothing ever releases an allocation for an object that was never
    /// actually created.
    #[tokio::test]
    async fn allocate_dry_run_all_does_not_reserve_a_sentinel() {
        use axum::extract::{Path, State};

        let state = make_state_with_cidr_for_resource_tests("10.96.0.0/29");

        let svc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "dry-run-svc", "namespace": "default" },
            "spec": { "type": "ClusterIP", "ports": [{ "port": 80 }] }
        });

        let _ = create_namespaced_resource(
            State(state.clone()),
            Path(("".into(), "v1".into(), "default".into(), "services".into())),
            axum::extract::Query(CreateQuery {
                dry_run: Some("All".to_string()),
                ..Default::default()
            }),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&svc).unwrap()),
        )
        .await
        .unwrap_or_else(|e| panic!("dry-run Service create must succeed: {e:?}"));

        let sentinels = state
            .store
            .list(
                crate::state::SERVICE_IP_PREFIX,
                u7s_store::ListOptions::default(),
            )
            .await
            .expect("list sentinels");
        assert_eq!(
            sentinels.items.len(),
            0,
            "dryRun=All must not reserve a clusterIP sentinel — every dry-run create would \
             otherwise permanently leak one IP from the pool"
        );
    }

    /// Creating 10 ClusterIP Services must produce 10 distinct clusterIPs.
    ///
    /// Duplicate clusterIPs mis-route traffic: two services sharing one IP means
    /// only one can be reached via kube-proxy iptables rules.
    #[tokio::test]
    async fn allocate_no_duplicates() {
        use axum::body::to_bytes;
        use axum::extract::{Path, State};
        use axum::response::IntoResponse;
        use std::collections::HashSet;

        // /24 has 254 usable IPs — enough for 10 services without exhaustion.
        let state = make_state_with_cidr_for_resource_tests("10.0.0.0/24");

        let mut ips: HashSet<String> = HashSet::new();
        for i in 0..10u32 {
            let svc = serde_json::json!({
                "apiVersion": "v1",
                "kind": "Service",
                "metadata": { "name": format!("svc-{i}"), "namespace": "default" },
                "spec": { "type": "ClusterIP", "ports": [{ "port": 80 }] }
            });
            let resp = create_namespaced_resource(
                State(state.clone()),
                Path(("".into(), "v1".into(), "default".into(), "services".into())),
                axum::extract::Query(CreateQuery::default()),
                test_user(),
                json_headers(),
                bytes::Bytes::from(serde_json::to_vec(&svc).unwrap()),
            )
            .await
            .unwrap_or_else(|e| panic!("Service {i} create must succeed: {e:?}"))
            .into_response();

            let body = to_bytes(resp.into_body(), usize::MAX).await.unwrap();
            let v: serde_json::Value = serde_json::from_slice(&body).unwrap();
            let ip = v["spec"]["clusterIP"].as_str().unwrap_or("").to_string();
            assert!(
                !ip.is_empty() && ip != "None",
                "Service {i} must get a clusterIP — empty means allocation is broken"
            );
            assert!(
                ips.insert(ip.clone()),
                "clusterIP {ip} for Service {i} duplicates an earlier allocation — \
                 duplicate IPs mis-route traffic"
            );
        }

        assert_eq!(
            ips.len(),
            10,
            "10 Services must produce 10 distinct clusterIPs"
        );
    }

    /// A headless Service (clusterIP: None) must NOT have a clusterIP auto-allocated.
    ///
    /// Headless services have no cluster IP; they return all Pod IPs directly via DNS.
    /// Auto-allocating an IP for them would break DNS round-robin and confuse kube-proxy.
    #[tokio::test]
    async fn headless_service_skips_allocation() {
        use axum::body::to_bytes;
        use axum::extract::{Path, State};
        use axum::response::IntoResponse;

        let state = make_state_with_cidr_for_resource_tests("10.0.0.0/24");

        let svc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "headless", "namespace": "default" },
            "spec": { "clusterIP": "None", "ports": [{ "port": 80 }] }
        });

        let resp = create_namespaced_resource(
            State(state),
            Path(("".into(), "v1".into(), "default".into(), "services".into())),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&svc).unwrap()),
        )
        .await
        .unwrap_or_else(|e| panic!("headless Service create must succeed: {e:?}"))
        .into_response();

        assert_eq!(resp.status(), axum::http::StatusCode::CREATED);
        let body = to_bytes(resp.into_body(), usize::MAX).await.unwrap();
        let v: serde_json::Value = serde_json::from_slice(&body).unwrap();

        assert_eq!(
            v["spec"]["clusterIP"].as_str(),
            Some("None"),
            "headless Service must retain clusterIP=None — overwriting it with an allocated IP \
             would break DNS round-robin by making the service behave like a normal ClusterIP service"
        );
    }

    /// A Service with a pre-set spec.clusterIP must keep that IP (static allocation).
