    /// Deleting a Job must remove the `batch.kubernetes.io/job-tracking` finalizer from
    /// owned pods so the GC cascade can complete.
    ///
    /// Without this fix KCM's job-controller receives a hard-delete event for the job,
    /// returns early from syncJob ("job not found"), and never removes the tracking
    /// finalizer from pods.  The pods are then stuck Terminating forever — GC cannot
    /// complete because the finalizer-holder (KCM) never acts.
    #[tokio::test]
    async fn delete_job_removes_tracking_finalizer_from_owned_pods() {
        let state = make_state();
        let job_uid = "job-uid-abc123";
        let ns = "test-ns";

        // Create a pod with batch.kubernetes.io/job-tracking finalizer, owned by the job.
        let pod_key = crate::keys::group_object_key("", "pods", Some(ns), "pod-1");
        let pod = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Pod",
            "metadata": {
                "name": "pod-1",
                "namespace": ns,
                "resourceVersion": "1",
                "uid": "pod-uid-1",
                "finalizers": ["batch.kubernetes.io/job-tracking"],
                "ownerReferences": [{
                    "apiVersion": "batch/v1",
                    "kind": "Job",
                    "name": "my-job",
                    "uid": job_uid,
                    "controller": true
                }]
            },
            "spec": {}
        });
        state
            .store
            .put(
                &pod_key,
                bytes::Bytes::from(serde_json::to_vec(&pod).unwrap()),
                None,
            )
            .await
            .expect("create pod");

        // Act: remove the tracking finalizer (simulating job hard-delete).
        remove_job_tracking_finalizer_from_pods(&state, ns, job_uid).await;

        // Assert: pod still exists but finalizers are cleared.
        let stored = state
            .store
            .get(&pod_key)
            .await
            .expect("store get")
            .expect("pod must still exist — no deletionTimestamp, so not hard-deleted");
        let stored_pod: serde_json::Value =
            serde_json::from_slice(&stored.value).expect("deserialize pod");
        let finalizers = stored_pod["metadata"]["finalizers"].as_array();
        assert!(
            finalizers.is_none() || finalizers.unwrap().is_empty(),
            "job-tracking finalizer must be removed from the pod so the GC cascade can \
             complete — without this, pods are stuck Terminating forever: \
             got finalizers = {:?}",
            stored_pod["metadata"]["finalizers"]
        );
    }

    /// When a job is deleted and a pod owned by it already has deletionTimestamp set AND
    /// has only the tracking finalizer (no other finalizers), the pod must be hard-deleted
    /// immediately so the GC sees a clean DELETED event.
    ///
    /// Without this: the pod is stuck in Terminating state indefinitely — deletionTimestamp
    /// is set but the finalizer prevents hard-delete, and no controller removes the finalizer.
    #[tokio::test]
    async fn delete_job_hard_deletes_terminating_pod_with_only_tracking_finalizer() {
        let state = make_state();
        let job_uid = "job-uid-xyz789";
        let ns = "test-ns2";

        // Create a pod that is already Terminating (has deletionTimestamp) + tracking finalizer.
        let pod_key = crate::keys::group_object_key("", "pods", Some(ns), "pod-term");
        let pod = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Pod",
            "metadata": {
                "name": "pod-term",
                "namespace": ns,
                "resourceVersion": "5",
                "uid": "pod-uid-term",
                "deletionTimestamp": "2026-01-01T00:00:00Z",
                "finalizers": ["batch.kubernetes.io/job-tracking"],
                "ownerReferences": [{
                    "apiVersion": "batch/v1",
                    "kind": "Job",
                    "name": "my-job2",
                    "uid": job_uid,
                    "controller": true
                }]
            },
            "spec": {}
        });
        state
            .store
            .put(
                &pod_key,
                bytes::Bytes::from(serde_json::to_vec(&pod).unwrap()),
                None,
            )
            .await
            .expect("create pod");

        // Act: remove the tracking finalizer.
        remove_job_tracking_finalizer_from_pods(&state, ns, job_uid).await;

        // Assert: pod must be hard-deleted (not found in store).
        let result = state.store.get(&pod_key).await.expect("store get");
        assert!(
            result.is_none(),
            "pod with deletionTimestamp + only tracking finalizer must be hard-deleted \
             when the job is deleted — without this, the GC cascade never completes and \
             the pod stays Terminating forever"
        );
    }

    // -- ownerReferences preserved through create ObjectMeta round-trip --

    /// create_namespaced_resource must persist ownerReferences from the incoming body.
    ///
    /// The create handler converts metadata through an ObjectMeta struct to set the
    /// namespace field.  ObjectMeta only declares the fields it explicitly knows about;
    /// any other field (including ownerReferences) is silently dropped by serde.  If
    /// ownerReferences are dropped during create, KCM-created Jobs (which carry an
    /// ownerReference to their CronJob) are stored without ownerReferences — the
    /// CronJob→Job cascade cannot match them, so the GC conformance spec
    /// "should delete jobs and pods created by cronjob" times out seeing 1 job / 1 pod
    /// after the CronJob is deleted.
    #[tokio::test]
    async fn create_namespaced_resource_preserves_owner_references() {
        use axum::extract::{Path, State};

        let state = make_state();
        let ns = "default";
        let cj_uid = "cj-uid-preserve-ownerrefs";

        // Create a Job with ownerReferences pointing to a CronJob — exactly what KCM
        // cronjob-controller does when it creates a Job from a CronJob schedule.
        let body = serde_json::json!({
            "apiVersion": "batch/v1",
            "kind": "Job",
            "metadata": {
                "name": "preserve-ownerrefs-job",
                "namespace": ns,
                "ownerReferences": [{
                    "apiVersion": "batch/v1",
                    "kind": "CronJob",
                    "name": "my-cronjob",
                    "uid": cj_uid,
                    "controller": true,
                    "blockOwnerDeletion": true
                }]
            },
            "spec": {
                "template": {
                    "spec": {
                        "containers": [{"name": "c", "image": "busybox"}],
                        "restartPolicy": "Never"
                    }
                }
            }
        });
        let body_bytes = bytes::Bytes::from(serde_json::to_vec(&body).unwrap());

        let result = create_namespaced_resource(
            State(state.clone()),
            Path(("batch".into(), "v1".into(), ns.to_string(), "jobs".into())),
            axum::extract::Query(CreateQuery::default()),
            axum::Extension(crate::auth::UserInfo {
                username: "admin".into(),
                uid: String::new(),
                groups: vec![],
                extra: Default::default(),
            }),
            axum::http::HeaderMap::new(),
            body_bytes,
        )
        .await
        .unwrap_or_else(|e| panic!("create Job must succeed: {e:?}"));

        // The stored object must have ownerReferences intact — if the ObjectMeta round-trip
        // drops them, the stored Job has no ownerReferences and the CronJob cascade cannot
        // identify it as owned, causing the GC conformance test to fail.
        let stored = state
            .store
            .get(&crate::keys::group_object_key(
                "batch",
                "jobs",
                Some(ns),
                "preserve-ownerrefs-job",
            ))
            .await
            .unwrap()
            .expect("Job must be stored");
        let stored_val: serde_json::Value =
            serde_json::from_slice(&stored.value).expect("stored Job must be valid JSON");
        let refs = stored_val["metadata"]["ownerReferences"].as_array().expect(
            "stored Job metadata.ownerReferences must be an array — if missing, the \
                 ObjectMeta round-trip in create_namespaced_resource dropped them, causing \
                 the CronJob→Job cascade to find no owned Jobs after CronJob deletion",
        );
        assert_eq!(refs.len(), 1, "one ownerReference must survive create");
        assert_eq!(
            refs[0]["kind"].as_str(),
            Some("CronJob"),
            "ownerReference.kind must be CronJob"
        );
        assert_eq!(
            refs[0]["uid"].as_str(),
            Some(cj_uid),
            "ownerReference.uid must match CronJob UID — cascade uses uid equality"
        );
        assert_eq!(
            refs[0]["controller"].as_bool(),
            Some(true),
            "controller field must survive the round-trip"
        );
        let _ = result;
    }

    // -- CronJob cascade --

    /// Deleting a CronJob must cascade-delete owned Jobs AND their pods, or the GC conformance
    /// spec "should delete jobs and pods created by cronjob" will time out polling for 0 jobs
    /// and 0 pods (observing 1 job / 1 pod for the full 60 s before "context deadline exceeded").
    #[tokio::test]
    async fn delete_cronjob_cascades_to_jobs_and_pods() {
        let state = make_state();
        let cj_uid = "cj-uid-aaaa-0001";
        let job_uid = "job-uid-bbbb-0001";
        let ns = "default";

        // Seed the CronJob.
        let cj_key = crate::keys::group_object_key("batch", "cronjobs", Some(ns), "my-cj");
        let cj = serde_json::json!({
            "apiVersion": "batch/v1",
            "kind": "CronJob",
            "metadata": { "name": "my-cj", "namespace": ns, "uid": cj_uid },
            "spec": { "schedule": "*/1 * * * *" }
        });
        state
            .store
            .put(
                &cj_key,
                bytes::Bytes::from(serde_json::to_vec(&cj).unwrap()),
                None,
            )
            .await
            .expect("seed CronJob");

        // Seed a Job owned by this CronJob (as KCM cronjob-controller creates it).
        let job_key = crate::keys::group_object_key("batch", "jobs", Some(ns), "my-cj-job");
        let job = serde_json::json!({
            "apiVersion": "batch/v1",
            "kind": "Job",
            "metadata": {
                "name": "my-cj-job",
                "namespace": ns,
                "uid": job_uid,
                "ownerReferences": [{
                    "apiVersion": "batch/v1",
                    "kind": "CronJob",
                    "name": "my-cj",
                    "uid": cj_uid,
                    "controller": true
                }]
            },
            "spec": { "template": { "spec": { "containers": [] } } }
        });
        state
            .store
            .put(
                &job_key,
                bytes::Bytes::from(serde_json::to_vec(&job).unwrap()),
                None,
            )
            .await
            .expect("seed Job");

        // Seed a Pod owned by the Job (as KCM job-controller creates it).
        let pod_key = crate::keys::group_object_key("", "pods", Some(ns), "my-cj-job-pod");
        let pod = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Pod",
            "metadata": {
                "name": "my-cj-job-pod",
                "namespace": ns,
                "ownerReferences": [{
                    "apiVersion": "batch/v1",
                    "kind": "Job",
                    "name": "my-cj-job",
                    "uid": job_uid,
                    "controller": true
                }]
            },
            "spec": { "containers": [{ "name": "c", "image": "busybox" }] }
        });
        state
            .store
            .put(
                &pod_key,
                bytes::Bytes::from(serde_json::to_vec(&pod).unwrap()),
                None,
            )
            .await
            .expect("seed Pod");

        // Delete the CronJob (default empty body — matches what the GC conformance test sends).
        delete_namespaced_resource(
            axum::extract::State(state.clone()),
            axum::extract::Path((
                "batch".into(),
                "v1".into(),
                ns.to_string(),
                "cronjobs".into(),
                "my-cj".into(),
            )),
            test_user(),
            axum::http::HeaderMap::new(),
            bytes::Bytes::new(),
        )
        .await
        .unwrap_or_else(|e| panic!("CronJob delete must succeed: {e:?}"));

        // CronJob itself must be gone.
        assert!(
            state.store.get(&cj_key).await.unwrap().is_none(),
            "CronJob itself must be hard-deleted"
        );

        // Job must be cascade-deleted — without this the GC conformance spec sees 'expected 0 jobs, got 1'.
        assert!(
            state.store.get(&job_key).await.unwrap().is_none(),
            "Job owned by deleted CronJob must be cascade-deleted — \
             GC conformance spec 'should delete jobs and pods created by cronjob' fails otherwise"
        );

        // Pod must be cascade-deleted — without this the spec sees 'expected 0 pods, got 1'.
        assert!(
            state.store.get(&pod_key).await.unwrap().is_none(),
            "Pod owned by Job owned by deleted CronJob must be cascade-deleted — \
             GC conformance spec 'should delete jobs and pods created by cronjob' fails otherwise \
             (two-level chain: CronJob->Job->Pod)"
        );
    }

    /// Deleting a CronJob with propagationPolicy=Orphan must NOT cascade-delete its Jobs or Pods.
    ///
    /// Explicit Orphan semantics must be honored for CronJob just as for every other resource:
    /// the CronJob soft-deletes with the `orphan` finalizer (the gate is generic, not
    /// RC/Deployment-specific — see add_orphan_finalizer) and its owned Jobs survive; real
    /// KCM's GC controller is responsible for stripping their ownerReferences, not u7s.
    #[tokio::test]
    async fn delete_cronjob_with_orphan_policy_does_not_cascade() {
        let state = make_state();
        let cj_uid = "cj-uid-cccc-0002";
        let job_uid = "job-uid-dddd-0002";
        let ns = "default";

        // Seed CronJob.
        let cj_key = crate::keys::group_object_key("batch", "cronjobs", Some(ns), "orphan-cj");
        let cj = serde_json::json!({
            "apiVersion": "batch/v1",
            "kind": "CronJob",
            "metadata": { "name": "orphan-cj", "namespace": ns, "uid": cj_uid },
            "spec": { "schedule": "*/1 * * * *" }
        });
        state
            .store
            .put(
                &cj_key,
                bytes::Bytes::from(serde_json::to_vec(&cj).unwrap()),
                None,
            )
            .await
            .expect("seed CronJob");

        // Seed a Job owned by the CronJob.
        let job_key = crate::keys::group_object_key("batch", "jobs", Some(ns), "orphan-cj-job");
        let job = serde_json::json!({
            "apiVersion": "batch/v1",
            "kind": "Job",
            "metadata": {
                "name": "orphan-cj-job",
                "namespace": ns,
                "uid": job_uid,
                "ownerReferences": [{
                    "apiVersion": "batch/v1",
                    "kind": "CronJob",
                    "name": "orphan-cj",
                    "uid": cj_uid,
                    "controller": true
                }]
            },
            "spec": { "template": { "spec": { "containers": [] } } }
        });
        state
            .store
            .put(
                &job_key,
                bytes::Bytes::from(serde_json::to_vec(&job).unwrap()),
                None,
            )
            .await
            .expect("seed Job");

        // Delete with propagationPolicy=Orphan.
        let orphan_body = bytes::Bytes::from(
            serde_json::to_vec(&serde_json::json!({
                "apiVersion": "v1",
                "kind": "DeleteOptions",
                "propagationPolicy": "Orphan"
            }))
            .unwrap(),
        );
        delete_namespaced_resource(
            axum::extract::State(state.clone()),
            axum::extract::Path((
                "batch".into(),
                "v1".into(),
                ns.to_string(),
                "cronjobs".into(),
                "orphan-cj".into(),
            )),
            test_user(),
            axum::http::HeaderMap::new(),
            orphan_body,
        )
        .await
        .unwrap_or_else(|e| panic!("Orphan delete must succeed: {e:?}"));

        // CronJob must be SOFT-deleted (deletionTimestamp + "orphan" finalizer), not
        // hard-deleted synchronously — same generic gate as RC/Deployment Orphan deletes.
        let cj_stored = state
            .store
            .get(&cj_key)
            .await
            .unwrap()
            .expect("CronJob must remain in the store (soft-deleted) after an Orphan delete");
        let cj_val: serde_json::Value = serde_json::from_slice(&cj_stored.value).unwrap();
        assert!(
            cj_val["metadata"]["deletionTimestamp"].is_string(),
            "Orphan delete must stamp deletionTimestamp on the CronJob"
        );
        assert_eq!(
            cj_val["metadata"]["finalizers"]
                .as_array()
                .and_then(|f| f.first())
                .and_then(|v| v.as_str()),
            Some("orphan"),
            "Orphan delete must add the `orphan` finalizer to the CronJob, same as any other \
             resource type"
        );

        // Job must survive — Orphan means do NOT cascade.
        assert!(
            state.store.get(&job_key).await.unwrap().is_some(),
            "Orphan delete of CronJob must leave its Jobs alive — \
             cascade on Orphan would contradict explicit Orphan semantics"
        );
    }

    // -- RoleBinding escalation prevention (bwm2) --

    /// A user without permission X who creates a RoleBinding granting a Role that contains X
    /// must get 403 Forbidden.  Without this check, any user with create rolebindings in a
    /// namespace can self-grant cluster-admin-in-namespace by binding to any powerful Role.
    #[tokio::test]
    async fn create_rolebinding_denied_for_user_lacking_role_rules() {
        use axum::extract::{Extension, Path, State};

        let state = make_state();
        let group = "rbac.authorization.k8s.io";
        let version = "v1";
        let ns = "default";

        // Seed a Role in "default" with secret-read rules that "alice" does NOT hold.
        let secret_role = serde_json::json!({
            "apiVersion": "rbac.authorization.k8s.io/v1",
            "kind": "Role",
            "metadata": {"name": "secret-reader", "namespace": ns},
            "rules": [{
                "apiGroups": [""],
                "resources": ["secrets"],
                "verbs": ["get", "list"]
            }]
        });
        let role_key = format!("/apis/{group}/{version}/namespaces/{ns}/roles/secret-reader");
        state.rbac_index.apply_object(&role_key, &secret_role);

        // "alice" can only create rolebindings — she does NOT have get/list secrets.
        let alice_cr = serde_json::json!({
            "rules": [{
                "apiGroups": [group],
                "resources": ["rolebindings"],
                "verbs": ["create"]
            }]
        });
        let alice_crb_key = format!("/apis/{group}/{version}/clusterroles/alice-rb-creator");
        state.rbac_index.apply_object(&alice_crb_key, &alice_cr);
        let alice_bind_key =
            format!("/apis/{group}/{version}/clusterrolebindings/alice-rb-creator-bind");
        let alice_bind = serde_json::json!({
            "subjects": [{"kind": "User", "name": "alice"}],
            "roleRef": {
                "apiGroup": group,
                "kind": "ClusterRole",
                "name": "alice-rb-creator"
            }
        });
        state.rbac_index.apply_object(&alice_bind_key, &alice_bind);

        // alice tries to bind herself to "secret-reader" in "default".
        let rb_body = serde_json::json!({
            "apiVersion": "rbac.authorization.k8s.io/v1",
            "kind": "RoleBinding",
            "metadata": {"name": "alice-secret-reader", "namespace": ns},
            "subjects": [{"kind": "User", "name": "alice"}],
            "roleRef": {
                "apiGroup": group,
                "kind": "Role",
                "name": "secret-reader"
            }
        });
        let alice_user = Extension(crate::auth::UserInfo {
            username: "alice".into(),
            uid: String::new(),
            groups: vec![],
            extra: Default::default(),
        });
        let result = create_namespaced_resource(
            State(state),
            Path((
                group.to_string(),
                version.to_string(),
                ns.to_string(),
                "rolebindings".to_string(),
            )),
            axum::extract::Query(CreateQuery::default()),
            alice_user,
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&rb_body).unwrap()),
        )
        .await;

        match result {
            Err(err) => assert_eq!(
                err.0,
                axum::http::StatusCode::FORBIDDEN,
                "missing RB escalation check lets any namespace rolebindings-creator \
                 self-grant cluster-admin-in-namespace; alice must be denied because \
                 she does not hold get/list secrets"
            ),
            Ok(_) => panic!(
                "missing RB escalation check lets any namespace rolebindings-creator \
                 self-grant cluster-admin-in-namespace; alice must be denied because \
                 she does not hold get/list secrets"
            ),
        }
    }

    /// A user who holds all the rules in a Role must be allowed to create a RoleBinding to it.
    /// This ensures that users with the right permissions can delegate them within a namespace.
    #[tokio::test]
    async fn create_rolebinding_allowed_for_user_holding_role_rules() {
        use axum::extract::{Extension, Path, State};
        use axum::http::StatusCode;
        use axum::response::IntoResponse;

        let state = make_state();
        let group = "rbac.authorization.k8s.io";
        let version = "v1";
        let ns = "default";

        // Seed a Role in "default" with pod-read rules.
        let pod_role = serde_json::json!({
            "apiVersion": "rbac.authorization.k8s.io/v1",
            "kind": "Role",
            "metadata": {"name": "pod-reader", "namespace": ns},
            "rules": [{
                "apiGroups": [""],
                "resources": ["pods"],
                "verbs": ["get", "list"]
            }]
        });
        let role_key = format!("/apis/{group}/{version}/namespaces/{ns}/roles/pod-reader");
        state.rbac_index.apply_object(&role_key, &pod_role);

        // Seed cluster-admin and system:masters binding so "admin" passes escalation.
        let admin_cr = serde_json::json!({
            "rules": [{"apiGroups": ["*"], "resources": ["*"], "verbs": ["*"]}]
        });
        state.rbac_index.apply_object(
            &format!("/apis/{group}/{version}/clusterroles/cluster-admin"),
            &admin_cr,
        );
        let masters_crb = serde_json::json!({
            "subjects": [{"kind": "Group", "name": "system:masters"}],
            "roleRef": {
                "apiGroup": group,
                "kind": "ClusterRole",
                "name": "cluster-admin"
            }
        });
        state.rbac_index.apply_object(
            &format!("/apis/{group}/{version}/clusterrolebindings/system-masters-cluster-admin"),
            &masters_crb,
        );

        // "admin" (system:masters) creates a RoleBinding granting pod-reader to "bob".
        let rb_body = serde_json::json!({
            "apiVersion": "rbac.authorization.k8s.io/v1",
            "kind": "RoleBinding",
            "metadata": {"name": "bob-pod-reader", "namespace": ns},
            "subjects": [{"kind": "User", "name": "bob"}],
            "roleRef": {
                "apiGroup": group,
                "kind": "Role",
                "name": "pod-reader"
            }
        });
        let admin_user = Extension(crate::auth::UserInfo {
            username: "admin".into(),
            uid: String::new(),
            groups: vec!["system:masters".into()],
            extra: Default::default(),
        });
        let result = create_namespaced_resource(
            State(state),
            Path((
                group.to_string(),
                version.to_string(),
                ns.to_string(),
                "rolebindings".to_string(),
            )),
            axum::extract::Query(CreateQuery::default()),
            admin_user,
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&rb_body).unwrap()),
        )
        .await;

        let status = result
            .map(|r| r.into_response().status())
            .unwrap_or_else(|e| {
                panic!(
                    "admin with system:masters must be allowed to create RoleBinding; got: {}",
                    e.1.message
                )
            });
        assert_eq!(
            status,
            StatusCode::CREATED,
            "admin who holds all pod-reader rules must be allowed to create a RoleBinding"
        );
    }

    // ---------------------------------------------------------------------------
    // Lease acquireTime/renewTime must be persisted and returned on GET
    // ---------------------------------------------------------------------------

    /// A Lease created with spec.acquireTime and spec.renewTime must return
    /// those fields non-nil on GET.
    ///
    /// The conformance spec '[sig-node] Lease lease API should be available
    /// [Conformance]' (k8s test/e2e/common/node/lease.go:99) creates a Lease with
    /// both timestamps set and asserts they are non-nil after create and update.
    /// If acquireTime or renewTime are dropped by the create or update path, the
    /// test fails with "unexpected nil acquireTime" or "unexpected nil renewTime".
    ///
    /// This test fails if apply_defaults, the metadata round-trip, or any other
    /// handler step strips spec fields from a Lease.
    #[tokio::test]
    async fn lease_acquire_and_renew_time_preserved_on_create_and_update() {
        use axum::body::to_bytes;
        use axum::extract::{Path, Query, State};
        use axum::response::IntoResponse;

        let state = make_state();

        let acquire_ts = "2026-06-29T12:00:00.000000Z";
        let renew_ts = "2026-06-29T12:00:01.000000Z";

        // Step 1: create a Lease with acquireTime and renewTime via PUT (upsert).
        let lease_v1 = serde_json::json!({
            "apiVersion": "coordination.k8s.io/v1",
            "kind": "Lease",
            "metadata": { "name": "test-lease", "namespace": "kube-node-lease" },
            "spec": {
                "holderIdentity": "node-1",
                "leaseDurationSeconds": 40,
                "acquireTime": acquire_ts,
                "renewTime": renew_ts,
                "leaseTransitions": 0
            }
        });
        let _ = replace_namespaced_resource(
            State(state.clone()),
            Path((
                "coordination.k8s.io".into(),
                "v1".into(),
                "kube-node-lease".into(),
                "leases".into(),
                "test-lease".into(),
            )),
            Query(ReplaceQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&lease_v1).unwrap()),
        )
        .await
        .unwrap_or_else(|e| panic!("Lease create must succeed: {e:?}"))
        .into_response();

        // Step 2: GET the Lease and check acquireTime/renewTime are present.
        let get_resp = get_namespaced_resource(
            State(state.clone()),
            Path((
                "coordination.k8s.io".into(),
                "v1".into(),
                "kube-node-lease".into(),
                "leases".into(),
                "test-lease".into(),
            )),
            axum::http::HeaderMap::new(),
        )
        .await
        .unwrap_or_else(|e| panic!("Lease GET must succeed: {e:?}"));

        let body = to_bytes(get_resp.into_body(), usize::MAX).await.unwrap();
        let v: serde_json::Value = serde_json::from_slice(&body).unwrap();

        assert_eq!(
            v["spec"]["acquireTime"].as_str(),
            Some(acquire_ts),
            "spec.acquireTime must be present after create — the Lease conformance test \
             ([sig-node] Lease lease API should be available) checks acquireTime != nil \
             after create; if dropped the test fails with 'unexpected nil acquireTime'"
        );
        assert_eq!(
            v["spec"]["renewTime"].as_str(),
            Some(renew_ts),
            "spec.renewTime must be present after create — the Lease conformance test \
             checks renewTime != nil after create; if dropped the test fails with \
             'unexpected nil renewTime'"
        );

        // Step 3: UPDATE via PUT with a new renewTime but same acquireTime.
        let new_renew_ts = "2026-06-29T12:00:41.000000Z";
        let stored_rv = v["metadata"]["resourceVersion"]
            .as_str()
            .unwrap_or("")
            .to_string();
        let lease_v2 = serde_json::json!({
            "apiVersion": "coordination.k8s.io/v1",
            "kind": "Lease",
            "metadata": {
                "name": "test-lease",
                "namespace": "kube-node-lease",
                "resourceVersion": stored_rv
            },
            "spec": {
                "holderIdentity": "node-1",
                "leaseDurationSeconds": 40,
                "acquireTime": acquire_ts,
                "renewTime": new_renew_ts,
                "leaseTransitions": 0
            }
        });
        let _ = replace_namespaced_resource(
            State(state.clone()),
            Path((
                "coordination.k8s.io".into(),
                "v1".into(),
                "kube-node-lease".into(),
                "leases".into(),
                "test-lease".into(),
            )),
            Query(ReplaceQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&lease_v2).unwrap()),
        )
        .await
        .unwrap_or_else(|e| panic!("Lease update must succeed: {e:?}"))
        .into_response();

        // Step 4: GET again — acquireTime must still be set, renewTime updated.
        let get_resp2 = get_namespaced_resource(
            State(state.clone()),
            Path((
                "coordination.k8s.io".into(),
                "v1".into(),
                "kube-node-lease".into(),
                "leases".into(),
                "test-lease".into(),
            )),
            axum::http::HeaderMap::new(),
        )
        .await
        .unwrap_or_else(|e| panic!("Lease second GET must succeed: {e:?}"));

        let body2 = to_bytes(get_resp2.into_body(), usize::MAX).await.unwrap();
        let v2: serde_json::Value = serde_json::from_slice(&body2).unwrap();

        assert_eq!(
            v2["spec"]["acquireTime"].as_str(),
            Some(acquire_ts),
            "spec.acquireTime must still be present after update — \
             the Lease conformance test checks acquireTime != nil after update too"
        );
        assert_eq!(
            v2["spec"]["renewTime"].as_str(),
            Some(new_renew_ts),
            "spec.renewTime must reflect the updated value after PUT update"
        );
    }

    // ---------------------------------------------------------------------------
    // Service ExternalName→ClusterIP type transition must allocate a clusterIP
    // ---------------------------------------------------------------------------

    /// Changing a Service from ExternalName to ClusterIP via PUT must result in a
    /// non-empty spec.clusterIP in the stored object.
    ///
    /// The conformance spec '[sig-network] Services should be able to change the type from
    /// ExternalName to ClusterIP [Conformance]' (network/service.go:1445) fails with
    /// "didn't get ClusterIP for non-ExternalName service" when the PUT on the main
    /// endpoint does not trigger ClusterIP allocation.  ExternalName services are created
    /// without a clusterIP; the update path must allocate one when the type changes.
    ///
    /// This test fails if maybe_allocate_cluster_ip is not called from
    /// replace_namespaced_resource.
    #[tokio::test]
    async fn externalname_to_clusterip_allocates_cluster_ip() {
        use axum::body::to_bytes;
        use axum::extract::{Path, Query, State};
        use axum::response::IntoResponse;
        use std::net::Ipv4Addr;
        use std::str::FromStr;

        let state = make_state_with_cidr_for_resource_tests("10.96.0.0/12");

        // Step 1: create an ExternalName service (no clusterIP).
        let svc_external = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "type-changer", "namespace": "default" },
            "spec": {
                "type": "ExternalName",
                "externalName": "my.external.host.example.com"
            }
        });
        let create_resp = create_namespaced_resource(
            State(state.clone()),
            Path(("".into(), "v1".into(), "default".into(), "services".into())),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&svc_external).unwrap()),
        )
        .await
        .unwrap_or_else(|e| panic!("ExternalName service create must succeed: {e:?}"))
        .into_response();
        assert_eq!(create_resp.status(), axum::http::StatusCode::CREATED);

        // Capture the resourceVersion for the PUT.
        let create_body = to_bytes(create_resp.into_body(), usize::MAX).await.unwrap();
        let created: serde_json::Value = serde_json::from_slice(&create_body).unwrap();
        let rv = created["metadata"]["resourceVersion"]
            .as_str()
            .unwrap_or("")
            .to_string();

        // Step 2: PUT to change type to ClusterIP — no clusterIP in body.
        let svc_clusterip = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": {
                "name": "type-changer",
                "namespace": "default",
                "resourceVersion": rv
            },
            "spec": {
                "type": "ClusterIP",
                "ports": [{ "port": 80 }]
            }
        });
        let put_resp = replace_namespaced_resource(
            State(state.clone()),
            Path((
                "".into(),
                "v1".into(),
                "default".into(),
                "services".into(),
                "type-changer".into(),
            )),
            Query(ReplaceQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&svc_clusterip).unwrap()),
        )
        .await
        .unwrap_or_else(|e| panic!("Service type-change PUT must succeed: {e:?}"))
        .into_response();

        assert_eq!(put_resp.status(), axum::http::StatusCode::OK);

        let put_body = to_bytes(put_resp.into_body(), usize::MAX).await.unwrap();
        let v: serde_json::Value = serde_json::from_slice(&put_body).unwrap();

        let cluster_ip = v["spec"]["clusterIP"].as_str().unwrap_or("").to_string();
        assert!(
            !cluster_ip.is_empty() && cluster_ip != "None",
            "after ExternalName→ClusterIP type change via PUT, spec.clusterIP must be \
             allocated — without this, the conformance test '[sig-network] Services should \
             be able to change the type from ExternalName to ClusterIP' fails with \
             'didn't get ClusterIP for non-ExternalName service'; got clusterIP={cluster_ip:?}"
        );

        // Must be a valid IPv4 address within the configured CIDR.
        let ip = Ipv4Addr::from_str(&cluster_ip).unwrap_or_else(|_| {
            panic!(
                "spec.clusterIP must be a valid IPv4 address after type change, got {cluster_ip}"
            )
        });
        let base = u32::from(Ipv4Addr::new(10, 96, 0, 0));
        let mask: u32 = !((1u32 << (32 - 12)) - 1);
        assert_eq!(
            u32::from(ip) & mask,
            base & mask,
            "allocated clusterIP {ip} must be within 10.96.0.0/12"
        );
    }

    // ---------------------------------------------------------------------------
    // Service spec.clusterIP immutability regression tests
    //
    // maybe_allocate_cluster_ip only ever fills in an empty clusterIP; before this
    // fix nothing stopped a caller with `patch`/`update` rights from rewriting an
    // already-allocated clusterIP onto a different address — e.g. one already
    // handed to a different Service — silently hijacking whatever DNS/proxy
    // routing still points at that VIP. If validate_service_cluster_ip_immutable
    // is removed or its call sites are dropped, these tests fail.
    // ---------------------------------------------------------------------------

    /// PATCH changing an already-allocated Service.spec.clusterIP to a different
    /// address must return 422, not silently rewrite the VIP.
    #[tokio::test]
    async fn patch_service_rejects_cluster_ip_change() {
        use axum::extract::{Path, Query, State};

        let state = make_state_with_cidr_for_resource_tests("10.96.0.0/12");
        let ns = "default";
        let svc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "cip-svc", "namespace": ns },
            "spec": { "type": "ClusterIP", "clusterIP": "10.96.0.5", "ports": [{ "port": 80 }] }
        });
        create_namespaced_resource(
            State(state.clone()),
            Path(("".into(), "v1".into(), ns.into(), "services".into())),
            Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&svc).unwrap()),
        )
        .await
        .expect("Service create with static clusterIP must succeed");

        let patch = serde_json::json!({ "spec": { "clusterIP": "10.96.0.99" } });
        let mut merge_headers = json_headers();
        merge_headers.insert(
            axum::http::header::CONTENT_TYPE,
            axum::http::HeaderValue::from_static("application/strategic-merge-patch+json"),
        );
        let result = patch_namespaced_resource(
            State(state),
            Path((
                "".into(),
                "v1".into(),
                ns.into(),
                "services".into(),
                "cip-svc".into(),
            )),
            Query(PatchQuery::default()),
            test_user(),
            merge_headers,
            bytes::Bytes::from(serde_json::to_vec(&patch).unwrap()),
        )
        .await;

        match result {
            Err(err) => assert_eq!(
                err.0,
                axum::http::StatusCode::UNPROCESSABLE_ENTITY,
                "PATCH rewriting an already-allocated clusterIP to a different address must \
                 return 422 — a caller with only `patch services` rights could otherwise \
                 repoint the VIP onto an address already allocated to a different Service"
            ),
            Ok(_) => panic!(
                "PATCH changing spec.clusterIP from 10.96.0.5 to 10.96.0.99 must be rejected — \
                 accepting it lets any patch-services caller collide a Service's VIP with \
                 another Service's allocated address"
            ),
        }
    }

    /// PUT changing an already-allocated Service.spec.clusterIP to a different
    /// address must return 422 — same protection, PUT path.
    #[tokio::test]
    async fn replace_service_rejects_cluster_ip_change() {
        use axum::body::to_bytes;
        use axum::extract::{Path, Query, State};
        use axum::response::IntoResponse;

        let state = make_state_with_cidr_for_resource_tests("10.96.0.0/12");
        let ns = "default";
        let svc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "cip-put-svc", "namespace": ns },
            "spec": { "type": "ClusterIP", "clusterIP": "10.96.0.6", "ports": [{ "port": 80 }] }
        });
        let create_resp = create_namespaced_resource(
            State(state.clone()),
            Path(("".into(), "v1".into(), ns.into(), "services".into())),
            Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&svc).unwrap()),
        )
        .await
        .expect("Service create with static clusterIP must succeed")
        .into_response();
        let create_body = to_bytes(create_resp.into_body(), usize::MAX).await.unwrap();
        let created: serde_json::Value = serde_json::from_slice(&create_body).unwrap();
        let rv = created["metadata"]["resourceVersion"]
            .as_str()
            .unwrap_or("")
            .to_string();

        let replacement = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "cip-put-svc", "namespace": ns, "resourceVersion": rv },
            "spec": {
                "type": "ClusterIP",
                "clusterIP": "10.96.0.199",
                "ports": [{ "port": 80 }]
            }
        });
        let result = replace_namespaced_resource(
            State(state),
            Path((
                "".into(),
                "v1".into(),
                ns.into(),
                "services".into(),
                "cip-put-svc".into(),
            )),
            Query(ReplaceQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&replacement).unwrap()),
        )
        .await;

        match result {
            Err(err) => assert_eq!(
                err.0,
                axum::http::StatusCode::UNPROCESSABLE_ENTITY,
                "PUT rewriting an already-allocated clusterIP to a different address must \
                 return 422 — the same VIP-collision risk as the PATCH path"
            ),
            Ok(_) => panic!(
                "PUT changing spec.clusterIP from 10.96.0.6 to 10.96.0.199 must be rejected — \
                 a full replace is not an escape hatch around clusterIP immutability"
            ),
        }
    }

    /// PATCH changing spec.clusterIP is exempted from the immutability check when the
    /// Service is transitioning to/from ExternalName.
    ///
    /// ExternalName Services carry no clusterIP at all — apply_defaults unconditionally
    /// clears the field for that type — so there is no VIP to protect against collision
    /// while either the stored or incoming type is ExternalName. This mirrors upstream's
    /// `validateUpgradeDowngradeClusterIPs`, which bails out entirely for ExternalName on
    /// either side. If the exemption regresses, ordinary type-transition patches (e.g. the
    /// conformance test flow that flips a Service to ExternalName) start failing with 422
    /// instead of completing the transition.
    #[tokio::test]
    async fn patch_service_allows_cluster_ip_change_during_externalname_transition() {
        use axum::body::to_bytes;
        use axum::extract::{Path, Query, State};
        use axum::response::IntoResponse;

        let state = make_state_with_cidr_for_resource_tests("10.96.0.0/12");
        let ns = "default";
        let svc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Service",
            "metadata": { "name": "cip-extname-svc", "namespace": ns },
            "spec": { "type": "ClusterIP", "clusterIP": "10.96.0.7", "ports": [{ "port": 80 }] }
        });
        create_namespaced_resource(
            State(state.clone()),
            Path(("".into(), "v1".into(), ns.into(), "services".into())),
            Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            bytes::Bytes::from(serde_json::to_vec(&svc).unwrap()),
        )
        .await
        .expect("Service create with static clusterIP must succeed");

        // Transition to ExternalName while ALSO explicitly changing clusterIP in the same
        // patch — this is the exact combination that would trip the immutability check
        // were it not exempted for an ExternalName transition.
        let patch = serde_json::json!({
            "spec": {
                "type": "ExternalName",
                "externalName": "my.external.host.example.com",
                "clusterIP": "10.96.0.177"
            }
        });
        let mut merge_headers = json_headers();
        merge_headers.insert(
            axum::http::header::CONTENT_TYPE,
            axum::http::HeaderValue::from_static("application/strategic-merge-patch+json"),
        );
        let resp = patch_namespaced_resource(
            State(state),
            Path((
                "".into(),
                "v1".into(),
                ns.into(),
                "services".into(),
                "cip-extname-svc".into(),
            )),
            Query(PatchQuery::default()),
            test_user(),
            merge_headers,
            bytes::Bytes::from(serde_json::to_vec(&patch).unwrap()),
        )
        .await
        .unwrap_or_else(|e| {
            panic!("PATCH transitioning a Service to ExternalName must succeed: {e:?}")
        })
        .into_response();

        assert_eq!(resp.status(), axum::http::StatusCode::OK);
        let body = to_bytes(resp.into_body(), usize::MAX).await.unwrap();
        let v: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(
            v["spec"]["type"], "ExternalName",
            "the type transition itself must have applied"
        );
        assert_eq!(
            v["spec"]["clusterIP"],
            serde_json::Value::String(String::new()),
            "an ExternalName Service must end up with clusterIP cleared, matching \
             default_service_spec, regardless of what clusterIP value the transitioning \
             patch carried"
        );
    }

    // ---------------------------------------------------------------------------
    // MockStore that injects a non-NotFound delete error on demand.
    //
    // Used by delete_collection error-propagation tests only.
    // ---------------------------------------------------------------------------

    struct FailOnDeleteStore {
        inner: std::sync::Arc<u7s_store::SqliteStore>,
        /// When true the *next* delete() call returns a storage error instead of
        /// delegating to the real store.  Cleared after firing once.
        arm: std::sync::atomic::AtomicBool,
    }

    impl FailOnDeleteStore {
        fn new() -> Self {
            Self {
                inner: std::sync::Arc::new(u7s_store::SqliteStore::new(":memory:").unwrap()),
                arm: std::sync::atomic::AtomicBool::new(false),
            }
        }

        fn arm(&self) {
            self.arm.store(true, std::sync::atomic::Ordering::SeqCst);
        }
    }

    impl u7s_store::Store for FailOnDeleteStore {
        fn get(
            &self,
            key: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Option<u7s_store::StoreObject>>> + Send
        {
            let inner = self.inner.clone();
            let key = key.to_string();
            async move { inner.get(&key).await }
        }

        fn list(
            &self,
            prefix: &str,
            opts: u7s_store::ListOptions,
        ) -> impl std::future::Future<Output = u7s_store::Result<u7s_store::ListResponse>> + Send
        {
            let inner = self.inner.clone();
            let prefix = prefix.to_string();
            async move { inner.list(&prefix, opts).await }
        }

        fn put(
            &self,
            key: &str,
            value: bytes::Bytes,
            expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<u64>> + Send {
            let inner = self.inner.clone();
            let key = key.to_string();
            async move { inner.put(&key, value, expected_revision).await }
        }

        fn delete(
            &self,
            key: &str,
            expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<(u64, bytes::Bytes)>> + Send
        {
            let inject = self.arm.swap(false, std::sync::atomic::Ordering::SeqCst);
            let inner = self.inner.clone();
            let key = key.to_string();
            async move {
                if inject {
                    // Simulate a storage-layer failure (revision mismatch is a concrete
                    // non-NotFound variant that requires no external crates to construct).
                    Err(u7s_store::StoreError::RevisionMismatch {
                        expected: 999,
                        current: 1,
                    })
                } else {
                    inner.delete(&key, expected_revision).await
                }
            }
        }

        fn list_namespace_objects(
            &self,
            namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<u7s_store::StoreObject>>> + Send
        {
            let inner = self.inner.clone();
            let ns = namespace.to_string();
            async move { inner.list_namespace_objects(&ns).await }
        }

        fn delete_namespace_resources(
            &self,
            namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<String>>> + Send {
            let inner = self.inner.clone();
            let ns = namespace.to_string();
            async move { inner.delete_namespace_resources(&ns).await }
        }

        fn watch(
            &self,
            _prefix: &str,
            _from_revision: u64,
        ) -> impl std::future::Future<
            Output = u7s_store::Result<
                impl futures_core::Stream<Item = u7s_store::WatchEvent> + Send + 'static,
            >,
        > + Send {
            std::future::ready(Ok(futures_util::stream::empty()))
        }

        fn compaction_horizon(&self) -> u64 {
            self.inner.compaction_horizon()
        }

        fn current_revision(&self) -> u64 {
            self.inner.current_revision()
        }

        fn watch_receiver_count(&self) -> usize {
            self.inner.watch_receiver_count()
        }
    }

    // ---------------------------------------------------------------------------
    // MockStore that, on the first armed put(), writes an INDEPENDENT object
    // (simulating a different concurrent writer, e.g. a status controller) instead
    // of the caller's own value, then reports RevisionMismatch.
    //
    // Used by strip_or_delete_dependent's and delete_resource's concurrent-write
    // regression tests.
    // ---------------------------------------------------------------------------

    struct ConcurrentWriterStore {
        inner: std::sync::Arc<u7s_store::SqliteStore>,
        concurrent_write: bytes::Bytes,
        inject_next: std::sync::atomic::AtomicBool,
    }

    impl ConcurrentWriterStore {
        fn new(
            inner: std::sync::Arc<u7s_store::SqliteStore>,
            concurrent_write: bytes::Bytes,
        ) -> Self {
            Self {
                inner,
                concurrent_write,
                inject_next: std::sync::atomic::AtomicBool::new(false),
            }
        }

        fn arm(&self) {
            self.inject_next
                .store(true, std::sync::atomic::Ordering::SeqCst);
        }
    }

    impl u7s_store::Store for ConcurrentWriterStore {
        fn get(
            &self,
            key: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Option<u7s_store::StoreObject>>> + Send
        {
            let inner = self.inner.clone();
            let key = key.to_string();
            async move { inner.get(&key).await }
        }

        fn list(
            &self,
            prefix: &str,
            opts: u7s_store::ListOptions,
        ) -> impl std::future::Future<Output = u7s_store::Result<u7s_store::ListResponse>> + Send
        {
            let inner = self.inner.clone();
            let prefix = prefix.to_string();
            async move { inner.list(&prefix, opts).await }
        }

        fn put(
            &self,
            key: &str,
            value: bytes::Bytes,
            expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<u64>> + Send {
            let inject = self
                .inject_next
                .swap(false, std::sync::atomic::Ordering::SeqCst);
            let inner = self.inner.clone();
            let key = key.to_string();
            let concurrent_write = self.concurrent_write.clone();
            async move {
                if inject {
                    // A different writer's change lands here, independent of `value`
                    // (the caller's own not-yet-persisted attempt).
                    let _ = inner.put(&key, concurrent_write, None).await;
                    Err(u7s_store::StoreError::RevisionMismatch {
                        expected: 1,
                        current: 99,
                    })
                } else {
                    inner.put(&key, value, expected_revision).await
                }
            }
        }

        fn delete(
            &self,
            key: &str,
            expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<(u64, bytes::Bytes)>> + Send
        {
            let inner = self.inner.clone();
            let key = key.to_string();
            async move { inner.delete(&key, expected_revision).await }
        }

        fn list_namespace_objects(
            &self,
            namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<u7s_store::StoreObject>>> + Send
        {
            let inner = self.inner.clone();
            let ns = namespace.to_string();
            async move { inner.list_namespace_objects(&ns).await }
        }

        fn delete_namespace_resources(
            &self,
            namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<String>>> + Send {
            let inner = self.inner.clone();
            let ns = namespace.to_string();
            async move { inner.delete_namespace_resources(&ns).await }
        }

        fn watch(
            &self,
            _prefix: &str,
            _from_revision: u64,
        ) -> impl std::future::Future<
            Output = u7s_store::Result<
                impl futures_core::Stream<Item = u7s_store::WatchEvent> + Send + 'static,
            >,
        > + Send {
            std::future::ready(Ok(futures_util::stream::empty()))
        }

        fn compaction_horizon(&self) -> u64 {
            self.inner.compaction_horizon()
        }

        fn current_revision(&self) -> u64 {
            self.inner.current_revision()
        }

        fn watch_receiver_count(&self) -> usize {
            self.inner.watch_receiver_count()
        }
    }

    // ---------------------------------------------------------------------------
    // MockStore that, on the first put(), writes an INDEPENDENT winner object
    // (simulating a second writer's create beating this request to the same
    // not-yet-existing name) instead of the caller's own value, then reports
    // AlreadyExists — forcing do_patch's SSA-create-race fallback branch
    // deterministically instead of relying on tokio::join! timing.
    //
    // Used by the SSA-create-race status-restore regression test.
    // ---------------------------------------------------------------------------

    struct RaceWinnerAlreadyExistsStore {
        inner: std::sync::Arc<u7s_store::SqliteStore>,
        winner_body: bytes::Bytes,
        fire_once: std::sync::atomic::AtomicBool,
    }

    impl RaceWinnerAlreadyExistsStore {
        fn new(inner: std::sync::Arc<u7s_store::SqliteStore>, winner_body: bytes::Bytes) -> Self {
            Self {
                inner,
                winner_body,
                fire_once: std::sync::atomic::AtomicBool::new(true),
            }
        }
    }

    impl u7s_store::Store for RaceWinnerAlreadyExistsStore {
        fn get(
            &self,
            key: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Option<u7s_store::StoreObject>>> + Send
        {
            let inner = self.inner.clone();
            let key = key.to_string();
            async move { inner.get(&key).await }
        }

        fn list(
            &self,
            prefix: &str,
            opts: u7s_store::ListOptions,
        ) -> impl std::future::Future<Output = u7s_store::Result<u7s_store::ListResponse>> + Send
        {
            let inner = self.inner.clone();
            let prefix = prefix.to_string();
            async move { inner.list(&prefix, opts).await }
        }

        fn put(
            &self,
            key: &str,
            value: bytes::Bytes,
            expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<u64>> + Send {
            let inject = self
                .fire_once
                .swap(false, std::sync::atomic::Ordering::SeqCst);
            let inner = self.inner.clone();
            let key = key.to_string();
            let winner_body = self.winner_body.clone();
            async move {
                if inject {
                    // A different writer's create lands here first, independent of
                    // `value` (the caller's own not-yet-persisted attempt).
                    inner
                        .put(&key, winner_body, None)
                        .await
                        .expect("seed race winner");
                    Err(u7s_store::StoreError::AlreadyExists { key })
                } else {
                    inner.put(&key, value, expected_revision).await
                }
            }
        }

        fn delete(
            &self,
            key: &str,
            expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<(u64, bytes::Bytes)>> + Send
        {
            let inner = self.inner.clone();
            let key = key.to_string();
            async move { inner.delete(&key, expected_revision).await }
        }

        fn list_namespace_objects(
            &self,
            namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<u7s_store::StoreObject>>> + Send
        {
            let inner = self.inner.clone();
            let ns = namespace.to_string();
            async move { inner.list_namespace_objects(&ns).await }
        }

        fn delete_namespace_resources(
            &self,
            namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<String>>> + Send {
            let inner = self.inner.clone();
            let ns = namespace.to_string();
            async move { inner.delete_namespace_resources(&ns).await }
        }

        fn watch(
            &self,
            _prefix: &str,
            _from_revision: u64,
        ) -> impl std::future::Future<
            Output = u7s_store::Result<
                impl futures_core::Stream<Item = u7s_store::WatchEvent> + Send + 'static,
            >,
        > + Send {
            std::future::ready(Ok(futures_util::stream::empty()))
        }

        fn compaction_horizon(&self) -> u64 {
            self.inner.compaction_horizon()
        }

        fn current_revision(&self) -> u64 {
            self.inner.current_revision()
        }

        fn watch_receiver_count(&self) -> usize {
            self.inner.watch_receiver_count()
        }
    }

    /// do_patch's SSA-create-race fallback (`is_ssa && stored_opt.is_none()`, then
    /// `CreateNamespacedError::Store(StoreError::AlreadyExists)`) restores the race
    /// winner's pre-merge stored status before persisting — the same status-subresource
    /// guard the main patch loop above already has (see `stored_status`), applied here to
    /// this separate merge-and-write. Without it, a request that loses the create race
    /// still gets its own SSA body's `status` field merged onto the winner's already-
    /// persisted object, bypassing the fact that `patch statefulsets` and `patch
    /// statefulsets/status` are separate RBAC grants.
    ///
    /// This test forces the race deterministically — a mock store injects the winner's
    /// object on the very first `put()`, simulating a second writer that beat this
    /// request to the create — instead of relying on `tokio::join!` timing, and the
    /// losing request's body carries a bare scalar for `status` (not an object), so a
    /// pass here proves the restore is an unconditional overwrite, not merely two objects
    /// happening to merge cleanly. Fails on revert: without the restore line, the scalar
    /// this request's own body carried ends up persisted in place of the winner's status.
    #[tokio::test]
    async fn ssa_create_race_fallback_restores_stored_status_over_scalar_body_status() {
        use axum::response::IntoResponse;
        use std::sync::Arc;
        use u7s_store::SqliteStore;

        let inner = Arc::new(SqliteStore::new(":memory:").expect("in-memory store"));
        let key = "/registry/apps/statefulsets/default/web";

        let winner = serde_json::json!({
            "apiVersion": "apps/v1",
            "kind": "StatefulSet",
            "metadata": { "name": "web", "namespace": "default" },
            "spec": {
                "replicas": 3,
                "selector": { "matchLabels": { "app": "web" } },
                "template": {
                    "metadata": { "labels": { "app": "web" } },
                    "spec": { "containers": [{ "name": "web", "image": "nginx" }] }
                }
            },
            "status": { "replicas": 3, "readyReplicas": 3 }
        });
        let winner_body = bytes::Bytes::from(serde_json::to_vec(&winner).unwrap());

        let store = Arc::new(RaceWinnerAlreadyExistsStore::new(
            inner.clone(),
            winner_body,
        ));
        let state = crate::state::AppState::new(
            store.clone(),
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        // This request loses the create race (the mock injects the winner first) and
        // lands in the AlreadyExists merge branch. Its "status" is a bare scalar: if the
        // restore below the merge didn't run, strategic_merge_patch would overwrite
        // current.body["status"] with it verbatim.
        let ssa_body = serde_json::json!({
            "apiVersion": "apps/v1",
            "kind": "StatefulSet",
            "metadata": { "name": "web", "namespace": "default" },
            "spec": {
                "replicas": 3,
                "selector": { "matchLabels": { "app": "web" } },
                "template": {
                    "metadata": { "labels": { "app": "web" } },
                    "spec": { "containers": [{ "name": "web", "image": "nginx" }] }
                }
            },
            "status": "forged-scalar-status"
        });

        let mut ssa_headers = axum::http::HeaderMap::new();
        ssa_headers.insert(
            axum::http::header::CONTENT_TYPE,
            axum::http::HeaderValue::from_static("application/apply-patch+yaml"),
        );

        let result = patch_namespaced_resource(
            axum::extract::State(state.clone()),
            axum::extract::Path((
                "apps".to_string(),
                "v1".to_string(),
                "default".to_string(),
                "statefulsets".to_string(),
                "web".to_string(),
            )),
            axum::extract::Query(PatchQuery::default()),
            test_user(),
            ssa_headers,
            bytes::Bytes::from(serde_json::to_vec(&ssa_body).unwrap()),
        )
        .await
        .unwrap_or_else(|e| panic!("race-fallback SSA merge must succeed: {e:?}"))
        .into_response();

        assert_eq!(
            result.status(),
            axum::http::StatusCode::OK,
            "the race-losing request must land in the AlreadyExists merge branch (200), not \
             the primary create path (201) — if this doesn't hold, the mock never forced \
             the race and this test isn't exercising the branch it exists to cover"
        );

        let stored = inner
            .get(key)
            .await
            .unwrap()
            .expect("the winner's StatefulSet must be persisted");
        let stored_body: serde_json::Value = serde_json::from_slice(&stored.value).unwrap();
        assert_eq!(
            stored_body["status"],
            serde_json::json!({ "replicas": 3, "readyReplicas": 3 }),
            "the SSA-create-race fallback must restore the pre-merge stored status, not \
             persist whatever the losing request's own body carried in `status` — if this \
             fails, a client without the status subresource grant can forge status just by \
             racing a create instead of PATCHing an already-existing object"
        );
    }

    /// `strip_or_delete_dependent` must re-read the dependent fresh and retry on conflict
    /// rather than blindly overwriting whatever the caller's LIST-time snapshot contained.
    ///
    /// If a concurrent writer (e.g. a status controller) updates the dependent between the
    /// cascade helper's LIST and this strip write, an unconditional `put(.., None)` of the
    /// stale snapshot would silently discard that write with no error to anyone — the
    /// writer believes its update succeeded. This test fails on revert: without the
    /// read-modify-write CAS retry, the concurrent write's `status.replicas` is clobbered
    /// back to its pre-race value.
    #[tokio::test]
    async fn strip_or_delete_dependent_retries_past_concurrent_write_instead_of_clobbering_it() {
        use std::sync::Arc;
        use u7s_store::SqliteStore;

        let inner = Arc::new(SqliteStore::new(":memory:").expect("in-memory store"));

        let owner_uid = "aaaa0000-0000-0000-0000-000000000001";
        let other_owner_uid = "bbbb0000-0000-0000-0000-000000000002";
        let ns = "default";

        // A second, still-live owner — keeps the dependent alive (strip path, not delete)
        // once `owner_uid`'s reference is removed.
        let other_owner_key = "/registry/apps/deployments/default/other-owner";
        inner
            .put(
                other_owner_key,
                bytes::Bytes::from(
                    serde_json::to_vec(&serde_json::json!({
                        "apiVersion": "apps/v1",
                        "kind": "Deployment",
                        "metadata": {
                            "name": "other-owner",
                            "namespace": ns,
                            "uid": other_owner_uid
                        }
                    }))
                    .unwrap(),
                ),
                None,
            )
            .await
            .unwrap();

        let owner_refs = serde_json::json!([
            {
                "apiVersion": "apps/v1", "kind": "Deployment",
                "name": "gone-owner", "uid": owner_uid, "controller": true
            },
            {
                "apiVersion": "apps/v1", "kind": "Deployment",
                "name": "other-owner", "uid": other_owner_uid
            }
        ]);

        let rs_key = "/registry/apps/replicasets/default/my-rs";
        let rs = serde_json::json!({
            "apiVersion": "apps/v1",
            "kind": "ReplicaSet",
            "metadata": {
                "name": "my-rs",
                "namespace": ns,
                "ownerReferences": owner_refs
            },
            "status": { "replicas": 0 }
        });
        inner
            .put(
                rs_key,
                bytes::Bytes::from(serde_json::to_vec(&rs).unwrap()),
                None,
            )
            .await
            .unwrap();

        // What a concurrent status controller's write lands as between strip's read and
        // its first write attempt — same ownerReferences, but an updated status field a
        // real client is relying on having durably persisted.
        let concurrent_write = serde_json::json!({
            "apiVersion": "apps/v1",
            "kind": "ReplicaSet",
            "metadata": {
                "name": "my-rs",
                "namespace": ns,
                "ownerReferences": owner_refs
            },
            "status": { "replicas": 3 }
        });
        let racing_store = Arc::new(ConcurrentWriterStore::new(
            Arc::clone(&inner),
            bytes::Bytes::from(serde_json::to_vec(&concurrent_write).unwrap()),
        ));
        racing_store.arm();

        let state = crate::state::AppState::new(
            racing_store,
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        let deleted = strip_or_delete_dependent(&state, ns, rs_key, owner_uid, "test-rs").await;

        assert!(
            !deleted,
            "the ReplicaSet has another live owner besides owner_uid, so it must survive \
             with only owner_uid's reference stripped, not be hard-deleted"
        );

        let stored = inner.get(rs_key).await.unwrap().unwrap();
        let stored_val: serde_json::Value = serde_json::from_slice(&stored.value).unwrap();

        let refs = stored_val["metadata"]["ownerReferences"]
            .as_array()
            .unwrap();
        assert!(
            !refs.iter().any(|r| r["uid"].as_str() == Some(owner_uid)),
            "the deleted owner's reference must be stripped"
        );
        assert!(
            refs.iter()
                .any(|r| r["uid"].as_str() == Some(other_owner_uid)),
            "the other live owner's reference must survive the strip"
        );
        assert_eq!(
            stored_val["status"]["replicas"], 3,
            "a concurrent status write racing the owner-ref strip must survive — a strip \
             that clobbers stale LIST-time data instead of retrying against the freshly \
             re-read object would silently discard a status update the writer believes \
             succeeded, with no error surfaced to either side"
        );
    }

    // ---------------------------------------------------------------------------
    // MockStore whose first put() always fails with AlreadyExists, regardless of key —
    // simulating a generateName suffix landing on some unrelated existing object.
    //
    // Used by create_namespaced_resource's generateName-collision-retry regression test.
    // ---------------------------------------------------------------------------

    struct FirstPutAlreadyExistsStore {
        inner: std::sync::Arc<u7s_store::SqliteStore>,
        fire_once: std::sync::atomic::AtomicBool,
    }

    impl FirstPutAlreadyExistsStore {
        fn new() -> Self {
            Self {
                inner: std::sync::Arc::new(u7s_store::SqliteStore::new(":memory:").unwrap()),
                fire_once: std::sync::atomic::AtomicBool::new(true),
            }
        }
    }

    impl u7s_store::Store for FirstPutAlreadyExistsStore {
        fn get(
            &self,
            key: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Option<u7s_store::StoreObject>>> + Send
        {
            let inner = self.inner.clone();
            let key = key.to_string();
            async move { inner.get(&key).await }
        }

        fn list(
            &self,
            prefix: &str,
            opts: u7s_store::ListOptions,
        ) -> impl std::future::Future<Output = u7s_store::Result<u7s_store::ListResponse>> + Send
        {
            let inner = self.inner.clone();
            let prefix = prefix.to_string();
            async move { inner.list(&prefix, opts).await }
        }

        fn put(
            &self,
            key: &str,
            value: bytes::Bytes,
            expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<u64>> + Send {
            let inject = self
                .fire_once
                .swap(false, std::sync::atomic::Ordering::SeqCst);
            let inner = self.inner.clone();
            let key = key.to_string();
            async move {
                if inject {
                    Err(u7s_store::StoreError::AlreadyExists { key })
                } else {
                    inner.put(&key, value, expected_revision).await
                }
            }
        }

        fn delete(
            &self,
            key: &str,
            expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<(u64, bytes::Bytes)>> + Send
        {
            let inner = self.inner.clone();
            let key = key.to_string();
            async move { inner.delete(&key, expected_revision).await }
        }

        fn list_namespace_objects(
            &self,
            namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<u7s_store::StoreObject>>> + Send
        {
            let inner = self.inner.clone();
            let ns = namespace.to_string();
            async move { inner.list_namespace_objects(&ns).await }
        }

        fn delete_namespace_resources(
            &self,
            namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<String>>> + Send {
            let inner = self.inner.clone();
            let ns = namespace.to_string();
            async move { inner.delete_namespace_resources(&ns).await }
        }

        fn watch(
            &self,
            _prefix: &str,
            _from_revision: u64,
        ) -> impl std::future::Future<
            Output = u7s_store::Result<
                impl futures_core::Stream<Item = u7s_store::WatchEvent> + Send + 'static,
            >,
        > + Send {
            std::future::ready(Ok(futures_util::stream::empty()))
        }

        fn compaction_horizon(&self) -> u64 {
            self.inner.compaction_horizon()
        }

        fn current_revision(&self) -> u64 {
            self.inner.current_revision()
        }

        fn watch_receiver_count(&self) -> usize {
            self.inner.watch_receiver_count()
        }
    }

    // ---------------------------------------------------------------------------
    // MockStore whose EVERY put() fails with AlreadyExists, counting attempts —
    // simulating exhausted generateName retries (every candidate name collides).
    //
    // Used by the retry-bound off-by-one regression test.
    // ---------------------------------------------------------------------------

    struct AlwaysAlreadyExistsStore {
        put_attempts: std::sync::atomic::AtomicU32,
    }

    impl AlwaysAlreadyExistsStore {
        fn new() -> Self {
            Self {
                put_attempts: std::sync::atomic::AtomicU32::new(0),
            }
        }

        fn put_attempts(&self) -> u32 {
            self.put_attempts.load(std::sync::atomic::Ordering::SeqCst)
        }
    }

    impl u7s_store::Store for AlwaysAlreadyExistsStore {
        fn get(
            &self,
            key: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Option<u7s_store::StoreObject>>> + Send
        {
            // A real "already exists" collision means a GET must find something at that
            // key — otherwise create_namespaced_resource's post-exhaustion 409 fallback
            // (which reads back "the" existing object to return in the response body)
            // sees a NotFound and turns it into a spurious 404 instead of the intended
            // 409. Content doesn't matter to the test, only that it round-trips as JSON.
            let value = bytes::Bytes::from(
                serde_json::to_vec(&serde_json::json!({
                    "apiVersion": "v1",
                    "kind": "PersistentVolumeClaim",
                    "metadata": { "name": "always-exists" }
                }))
                .unwrap(),
            );
            std::future::ready(Ok(Some(u7s_store::StoreObject {
                key: key.to_string(),
                value,
                revision: 1,
            })))
        }

        fn list(
            &self,
            _prefix: &str,
            _opts: u7s_store::ListOptions,
        ) -> impl std::future::Future<Output = u7s_store::Result<u7s_store::ListResponse>> + Send
        {
            std::future::ready(Ok(u7s_store::ListResponse {
                items: Vec::new(),
                revision: 0,
                continue_key: None,
                remaining_count: None,
            }))
        }

        fn put(
            &self,
            key: &str,
            _value: bytes::Bytes,
            _expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<u64>> + Send {
            self.put_attempts
                .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            let key = key.to_string();
            async move { Err(u7s_store::StoreError::AlreadyExists { key }) }
        }

        fn delete(
            &self,
            key: &str,
            _expected_revision: Option<u64>,
        ) -> impl std::future::Future<Output = u7s_store::Result<(u64, bytes::Bytes)>> + Send
        {
            let key = key.to_string();
            async move { Err(u7s_store::StoreError::NotFound { key }) }
        }

        fn list_namespace_objects(
            &self,
            _namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<u7s_store::StoreObject>>> + Send
        {
            std::future::ready(Ok(Vec::new()))
        }

        fn delete_namespace_resources(
            &self,
            _namespace: &str,
        ) -> impl std::future::Future<Output = u7s_store::Result<Vec<String>>> + Send {
            std::future::ready(Ok(Vec::new()))
        }

        fn watch(
            &self,
            _prefix: &str,
            _from_revision: u64,
        ) -> impl std::future::Future<
            Output = u7s_store::Result<
                impl futures_core::Stream<Item = u7s_store::WatchEvent> + Send + 'static,
            >,
        > + Send {
            std::future::ready(Ok(futures_util::stream::empty()))
        }

        fn compaction_horizon(&self) -> u64 {
            0
        }

        fn current_revision(&self) -> u64 {
            0
        }

        fn watch_receiver_count(&self) -> usize {
            0
        }
    }

    /// Start an axum router on a random local TCP port and return its base URL.
    ///
    /// Local to this module rather than shared with `admission.rs`'s identical test-only
    /// helper: each test module already owns its mock `Store` types the same way (see
    /// `FirstPutAlreadyExistsStore` above vs `admission.rs`'s equivalents) — one file's
    /// `#[cfg(test)] mod tests` isn't visible from another.
    async fn start_mock_admission_webhook_server(
        router: axum::Router,
    ) -> (String, tokio::task::JoinHandle<()>) {
        use tokio::net::TcpListener;
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let handle = tokio::spawn(async move {
            axum::serve(listener, router)
                .await
                .expect("mock webhook server must not fail");
        });
        (format!("http://{addr}"), handle)
    }

    /// upstream's pvc-deletion-performance spec (`test/e2e/storage/testsuites/pvcdeletionperf.go`)
    /// creates hundreds of PVCs in a tight loop using bare `metadata.generateName` — the client
    /// never chose a name and has no way to retry a collision itself. Before this fix,
    /// `create_namespaced_resource` generated exactly one candidate name and surfaced ANY
    /// store-level `AlreadyExists` straight to the client as a 409 on what looks like a plain
    /// create, even though the client-side symptom is indistinguishable from a random suffix
    /// landing on an unrelated object — a case upstream's own generic registry retries up to 8
    /// times with a fresh suffix (`createWithGenerateNameRetry`) rather than ever surfacing to
    /// the caller. This test fails on revert: it forces the very first put() to report
    /// AlreadyExists regardless of key, and asserts the create still succeeds.
    #[tokio::test]
    async fn create_namespaced_resource_retries_generate_name_collision_instead_of_409ing() {
        use axum::extract::{Path, State};
        use std::sync::Arc;

        let store = Arc::new(FirstPutAlreadyExistsStore::new());
        let state = crate::state::AppState::new(
            store,
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        let pvc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "PersistentVolumeClaim",
            "metadata": { "generateName": "pvc-", "namespace": "default" },
            "spec": {
                "accessModes": ["ReadWriteOnce"],
                "resources": { "requests": { "storage": "1Gi" } }
            }
        });
        let body = bytes::Bytes::from(serde_json::to_vec(&pvc).unwrap());

        let response = create_namespaced_resource(
            State(state),
            Path((
                "".into(),
                "v1".into(),
                "default".into(),
                "persistentvolumeclaims".into(),
            )),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            body,
        )
        .await
        .unwrap_or_else(|e| {
            panic!(
                "a generateName create must retry past a spurious collision, not hard-error: {e:?}"
            )
        })
        .into_response();

        assert_eq!(
            response.status(),
            axum::http::StatusCode::CREATED,
            "a generateName-based create must retry with a fresh suffix on AlreadyExists and \
             succeed, not surface a 409 the client never asked for and cannot retry itself"
        );
    }

    /// The cluster-scoped sibling of `create_namespaced_resource_retries_generate_name_
    /// collision_instead_of_409ing` above: `create_resource` has the identical
    /// generateName-collision-retry loop, so it must retry past a spurious store-level
    /// AlreadyExists the same way. This test fails on revert: it forces the very first
    /// put() to report AlreadyExists regardless of key, and asserts the create still
    /// succeeds instead of surfacing a 409.
    #[tokio::test]
    async fn create_resource_retries_generate_name_collision_instead_of_409ing() {
        use axum::extract::{Path, State};
        use std::sync::Arc;

        let store = Arc::new(FirstPutAlreadyExistsStore::new());
        let state = crate::state::AppState::new(
            store,
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        // Node is cluster-scoped, matching create_resource's scope; a bare generateName
        // (no explicit name) puts it through the same retry path a namespaced resource uses.
        let node = serde_json::json!({
            "apiVersion": "v1",
            "kind": "Node",
            "metadata": { "generateName": "node-" }
        });
        let admin = Extension(crate::auth::UserInfo {
            username: "admin".into(),
            uid: String::new(),
            groups: vec!["system:masters".into()],
            extra: Default::default(),
        });
        let body = bytes::Bytes::from(serde_json::to_vec(&node).unwrap());

        let response = create_resource(
            State(state),
            Path(("".into(), "v1".into(), "nodes".into())),
            axum::extract::Query(CreateQuery::default()),
            admin,
            json_headers(),
            body,
        )
        .await
        .unwrap_or_else(|e| {
            panic!(
                "a generateName create must retry past a spurious collision, not hard-error: {e:?}"
            )
        })
        .into_response();

        assert_eq!(
            response.status(),
            axum::http::StatusCode::CREATED,
            "a generateName-based create on the cluster-scoped handler must retry with a \
             fresh suffix on AlreadyExists and succeed, not surface a 409 the client never \
             asked for and cannot retry itself"
        );
    }

    /// If every candidate name collides (pathological, but the retry budget must still be
    /// bounded), the loop must give up after exactly `MAX_GENERATE_NAME_CREATE_ATTEMPTS`
    /// TOTAL `put()` calls — matching upstream's `maxNameGenerationCreateAttempts`, which
    /// counts the first attempt plus retries, not retries alone. An off-by-one here either
    /// makes one fewer real attempt than upstream (spurious 409 one collision earlier than
    /// necessary) or one extra (an unbounded-looking retry burst under sustained collisions).
    /// This test fails on revert of the attempt-counting fix: it forces AlreadyExists on
    /// EVERY put() and asserts the exact call count.
    #[tokio::test]
    async fn create_namespaced_resource_generate_name_retry_gives_up_after_exactly_max_attempts() {
        use axum::extract::{Path, State};
        use std::sync::Arc;

        let store = Arc::new(AlwaysAlreadyExistsStore::new());
        let state = crate::state::AppState::new(
            store.clone(),
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        let pvc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "PersistentVolumeClaim",
            "metadata": { "generateName": "pvc-", "namespace": "default" },
            "spec": {
                "accessModes": ["ReadWriteOnce"],
                "resources": { "requests": { "storage": "1Gi" } }
            }
        });
        let body = bytes::Bytes::from(serde_json::to_vec(&pvc).unwrap());

        let response = create_namespaced_resource(
            State(state),
            Path((
                "".into(),
                "v1".into(),
                "default".into(),
                "persistentvolumeclaims".into(),
            )),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            body,
        )
        .await
        .unwrap_or_else(|e| {
            panic!("an exhausted generateName retry must 409, not hard-error: {e:?}")
        })
        .into_response();

        assert_eq!(
            response.status(),
            axum::http::StatusCode::CONFLICT,
            "once every retry attempt has also collided, the client must finally see a \
             409 rather than the server retrying forever"
        );
        assert_eq!(
            store.put_attempts(),
            MAX_GENERATE_NAME_CREATE_ATTEMPTS,
            "must stop at exactly MAX_GENERATE_NAME_CREATE_ATTEMPTS total put() calls \
             (upstream's maxNameGenerationCreateAttempts counts the first attempt plus \
             retries) — one more or one fewer is an off-by-one in the retry bound"
        );
    }

    /// The retry loop must re-validate a REGENERATED generateName candidate against
    /// validating admission, not just the discarded first candidate — mirrors upstream's
    /// `createWithGenerateNameRetry`, which invokes `createValidation` once per attempt.
    /// Without this, a validating policy that inspects `metadata.name` (e.g. a
    /// naming-convention check) would validate a name that never gets persisted and never
    /// see the name that actually lands in the store after a collision retry.
    ///
    /// Regression test: forces exactly one store-level AlreadyExists (one retry) and
    /// asserts the mock webhook was invoked twice. If validating admission moves back
    /// outside the retry loop, the webhook is only ever called once and this test fails.
    #[tokio::test]
    async fn create_namespaced_resource_revalidates_regenerated_name_on_generate_name_retry() {
        use axum::extract::{Path, State};
        use axum::routing::post;
        use axum::Router;
        use std::sync::atomic::{AtomicU32, Ordering};
        use std::sync::Arc;

        let call_count = Arc::new(AtomicU32::new(0));
        let counter = call_count.clone();
        let router = Router::new().route(
            "/validate",
            post(move || {
                let counter = counter.clone();
                async move {
                    counter.fetch_add(1, Ordering::SeqCst);
                    axum::Json(serde_json::json!({
                        "apiVersion": "admission.k8s.io/v1",
                        "kind": "AdmissionReview",
                        "response": { "uid": "uid-retry-validate", "allowed": true }
                    }))
                }
            }),
        );
        let (base_url, _handle) = start_mock_admission_webhook_server(router).await;

        let store = Arc::new(FirstPutAlreadyExistsStore::new());

        // Seed straight into the wrapped SqliteStore, NOT through `store.put()` — the
        // wrapper's fire-once AlreadyExists injection must be reserved for the PVC create
        // below, not consumed by this unrelated setup write.
        let vwc = serde_json::json!({
            "apiVersion": "admissionregistration.k8s.io/v1",
            "kind": "ValidatingWebhookConfiguration",
            "metadata": {"name": "pvc-retry-revalidate-vwc"},
            "webhooks": [{
                "name": "pvc.count-calls.example.com",
                "clientConfig": { "url": format!("{base_url}/validate") },
                "rules": [{"apiGroups": ["*"], "apiVersions": ["*"], "resources": ["*"], "operations": ["CREATE"]}],
                "failurePolicy": "Fail"
            }]
        });
        store
            .inner
            .put(
                "/registry/admissionregistration.k8s.io/validatingwebhookconfigurations/pvc-retry-revalidate-vwc",
                bytes::Bytes::from(serde_json::to_vec(&vwc).unwrap()),
                None,
            )
            .await
            .unwrap();

        let state = crate::state::AppState::new(
            store,
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        let pvc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "PersistentVolumeClaim",
            "metadata": { "generateName": "pvc-", "namespace": "default" },
            "spec": {
                "accessModes": ["ReadWriteOnce"],
                "resources": { "requests": { "storage": "1Gi" } }
            }
        });
        let body = bytes::Bytes::from(serde_json::to_vec(&pvc).unwrap());

        let response = create_namespaced_resource(
            State(state),
            Path((
                "".into(),
                "v1".into(),
                "default".into(),
                "persistentvolumeclaims".into(),
            )),
            axum::extract::Query(CreateQuery::default()),
            test_user(),
            json_headers(),
            body,
        )
        .await
        .unwrap_or_else(|e| panic!("an always-allow webhook must never block the create: {e:?}"))
        .into_response();

        assert_eq!(
            response.status(),
            axum::http::StatusCode::CREATED,
            "an always-allow webhook must never block the create"
        );
        assert_eq!(
            call_count.load(Ordering::SeqCst),
            2,
            "the generateName collision retry must re-run validating admission against the \
             regenerated name — a count of 1 means the retried name bypassed admission \
             entirely (validation only ever ran for the first, discarded candidate)"
        );
    }

    /// A plain `kubectl delete pvc` (no resourceVersion precondition — matches
    /// `metav1.DeleteOptions{}`, exactly what client-go's typed Delete sends) must never
    /// surface a 409 caused by u7s's OWN internal read-then-CAS-write racing a concurrent
    /// writer. Real KCM's `pvc-protection-controller` stamps `kubernetes.io/pvc-protection`
    /// onto a PVC moments after creation — if that write lands between
    /// `delete_namespaced_resource`'s internal read and its internal soft-delete `put`, the
    /// delete must retry against the fresh object rather than reject the client's DELETE with
    /// a concurrency error it never asked to guard against (this exact race
    /// failed the sig-storage PV/PVC lifecycle conformance test — a client-observable 409 for
    /// a request the client-go DELETE call gave the server zero precondition information for).
    #[tokio::test]
    async fn delete_namespaced_resource_retries_past_concurrent_finalizer_write_instead_of_409ing()
    {
        use std::sync::Arc;
        use u7s_store::SqliteStore;

        let inner = Arc::new(SqliteStore::new(":memory:").expect("in-memory store"));

        let pvc_key = "/registry/persistentvolumeclaims/default/pvc-repro";
        let pvc = serde_json::json!({
            "apiVersion": "v1",
            "kind": "PersistentVolumeClaim",
            "metadata": {
                "name": "pvc-repro",
                "namespace": "default",
                "resourceVersion": "1",
                "finalizers": ["kubernetes.io/pvc-protection"]
            },
            "spec": {},
            "status": {"phase": "Pending"}
        });
        inner
            .put(
                pvc_key,
                bytes::Bytes::from(serde_json::to_vec(&pvc).unwrap()),
                None,
            )
            .await
            .unwrap();

        // What a second concurrent writer (e.g. a labeling client, or KCM reprocessing with a
        // stale informer cache) lands as between delete_namespaced_resource's read and its
        // first soft-delete write attempt — same finalizer, plus a label the DELETE's retry
        // must not clobber.
        let concurrent_write = serde_json::json!({
            "apiVersion": "v1",
            "kind": "PersistentVolumeClaim",
            "metadata": {
                "name": "pvc-repro",
                "namespace": "default",
                "resourceVersion": "1",
                "finalizers": ["kubernetes.io/pvc-protection"],
                "labels": {"raced": "true"}
            },
            "spec": {},
            "status": {"phase": "Pending"}
        });
        let racing_store = Arc::new(ConcurrentWriterStore::new(
            Arc::clone(&inner),
            bytes::Bytes::from(serde_json::to_vec(&concurrent_write).unwrap()),
        ));
        racing_store.arm();

        let state = crate::state::AppState::new(
            racing_store,
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        let result = delete_namespaced_resource(
            axum::extract::State(state),
            axum::extract::Path((
                String::new(),
                "v1".into(),
                "default".into(),
                "persistentvolumeclaims".into(),
                "pvc-repro".into(),
            )),
            test_user(),
            axum::http::HeaderMap::new(),
            bytes::Bytes::new(),
        )
        .await;

        assert!(
            result.is_ok(),
            "a plain DELETE (no resourceVersion precondition) must retry past a concurrent \
             pvc-protection finalizer write and succeed rather than surfacing the server's own \
             internal CAS conflict as a 409 the client never asked to guard against — got {:?}",
            result.err().map(|e| e.0)
        );

        let stored = inner.get(pvc_key).await.unwrap().unwrap();
        let stored_body: serde_json::Value = serde_json::from_slice(&stored.value).unwrap();
        assert!(
            stored_body["metadata"]["deletionTimestamp"].is_string(),
            "the retried delete must still stamp deletionTimestamp so garbage collection \
             actually proceeds — a retry that only avoided the 409 without completing the \
             soft-delete write would leave the PVC live forever with the client believing \
             DELETE succeeded"
        );
        assert_eq!(
            stored_body["metadata"]["labels"]["raced"], "true",
            "the concurrent writer's label must survive the retried delete — a delete that \
             retries by clobbering stale LIST-time data instead of re-reading the freshly \
             written object would silently discard that writer's change"
        );
    }

    /// A dependent with a second, still-live owner must survive `strip_or_delete_dependent`
    /// with only the deleted owner's reference removed. This is the core GC invariant: a
    /// cascade delete from one owner must never destroy a resource another live owner still
    /// legitimately references (see the doc comment on `strip_or_delete_dependent`).
    #[tokio::test]
    async fn strip_or_delete_dependent_preserves_dependent_with_live_second_owner() {
        use std::sync::Arc;
        use u7s_store::SqliteStore;

        let store = Arc::new(SqliteStore::new(":memory:").expect("in-memory store"));
        let ns = "default";
        let stale_owner_uid = "stale-owner-uid";
        let live_owner_uid = "live-owner-uid";

        store
            .put(
                "/registry/apps/deployments/default/live-owner",
                bytes::Bytes::from(
                    serde_json::to_vec(&serde_json::json!({
                        "apiVersion": "apps/v1",
                        "kind": "Deployment",
                        "metadata": { "name": "live-owner", "namespace": ns, "uid": live_owner_uid }
                    }))
                    .unwrap(),
                ),
                None,
            )
            .await
            .unwrap();

        let dependent_key = "/registry/apps/replicasets/default/my-rs";
        store
            .put(
                dependent_key,
                bytes::Bytes::from(
                    serde_json::to_vec(&serde_json::json!({
                        "apiVersion": "apps/v1",
                        "kind": "ReplicaSet",
                        "metadata": {
                            "name": "my-rs",
                            "namespace": ns,
                            "ownerReferences": [
                                { "apiVersion": "apps/v1", "kind": "Deployment", "name": "deleted-owner", "uid": stale_owner_uid },
                                { "apiVersion": "apps/v1", "kind": "Deployment", "name": "live-owner", "uid": live_owner_uid }
                            ]
                        }
                    }))
                    .unwrap(),
                ),
                None,
            )
            .await
            .unwrap();

        let state = crate::state::AppState::new(
            store.clone(),
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        let deleted =
            strip_or_delete_dependent(&state, ns, dependent_key, stale_owner_uid, "test-rs").await;
        assert!(
            !deleted,
            "the ReplicaSet has another live owner besides the deleted one, so it must \
             survive with only the deleted owner's reference stripped"
        );

        let stored = store.get(dependent_key).await.unwrap().unwrap();
        let stored_val: serde_json::Value = serde_json::from_slice(&stored.value).unwrap();
        let refs = stored_val["metadata"]["ownerReferences"]
            .as_array()
            .unwrap();
        assert!(
            !refs
                .iter()
                .any(|r| r["uid"].as_str() == Some(stale_owner_uid)),
            "the deleted owner's reference must be stripped"
        );
        assert!(
            refs.iter()
                .any(|r| r["uid"].as_str() == Some(live_owner_uid)),
            "the live owner's reference must survive — dropping it would orphan the \
             dependent from an owner that still exists"
        );
    }

    /// A dependent whose only other ownerReferences entry points to a UID that no longer
    /// exists in the store must be hard-deleted, not left behind with a dangling reference.
    /// Without this, a ReplicaSet whose sole owners were both deleted would linger forever
    /// instead of being garbage-collected.
    #[tokio::test]
    async fn strip_or_delete_dependent_hard_deletes_when_no_other_owner_is_live() {
        use std::sync::Arc;
        use u7s_store::SqliteStore;

        let store = Arc::new(SqliteStore::new(":memory:").expect("in-memory store"));
        let ns = "default";
        let stale_owner_uid = "stale-owner-uid";
        let other_dead_uid = "other-dead-uid";

        let dependent_key = "/registry/apps/replicasets/default/my-rs";
        store
            .put(
                dependent_key,
                bytes::Bytes::from(
                    serde_json::to_vec(&serde_json::json!({
                        "apiVersion": "apps/v1",
                        "kind": "ReplicaSet",
                        "metadata": {
                            "name": "my-rs",
                            "namespace": ns,
                            "ownerReferences": [
                                { "apiVersion": "apps/v1", "kind": "Deployment", "name": "deleted-owner", "uid": stale_owner_uid },
                                { "apiVersion": "apps/v1", "kind": "Deployment", "name": "also-gone", "uid": other_dead_uid }
                            ]
                        }
                    }))
                    .unwrap(),
                ),
                None,
            )
            .await
            .unwrap();

        let state = crate::state::AppState::new(
            store.clone(),
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        let deleted =
            strip_or_delete_dependent(&state, ns, dependent_key, stale_owner_uid, "test-rs").await;
        assert!(
            deleted,
            "no other owner is live, so the dependent must be hard-deleted rather than left \
             behind with only a dangling reference to a gone owner"
        );
        assert!(
            store.get(dependent_key).await.unwrap().is_none(),
            "the dependent must actually be removed from the store"
        );
    }

    /// delete_collection_resource must propagate a non-NotFound store error rather than
    /// returning 200 Success.  Silent swallowing causes quota drift: the client believes
    /// all objects were deleted, but some may survive because the store rejected the delete.
    ///
    /// Revert the match-on-delete fix (back to `let _ = …`) and this test fails.
    #[tokio::test]
    async fn delete_collection_resource_propagates_non_notfound_store_error() {
        use axum::extract::{Path, Query, State};

        let mock = std::sync::Arc::new(FailOnDeleteStore::new());
        let state = crate::state::AppState::new(
            mock.clone(),
            None,
            None,
            std::collections::HashMap::new(),
            "https://localhost:6443".into(),
        );

        // Seed one ClusterRoleBinding (non-seeded name so it is not skipped).
        let key = crate::keys::group_object_key(
            "rbac.authorization.k8s.io",
            "clusterrolebindings",
            None,
            "test-binding",
        );
        let val = serde_json::json!({
            "apiVersion": "rbac.authorization.k8s.io/v1",
            "kind": "ClusterRoleBinding",
            "metadata": { "name": "test-binding" },
        });
        mock.inner
            .put(
                &key,
                bytes::Bytes::from(serde_json::to_vec(&val).unwrap()),
                None,
            )
            .await
            .expect("seed must succeed");

        // Arm the store to fail on the next delete.
        mock.arm();

        let result = delete_collection_resource(
            State(state),
            Path((
                "rbac.authorization.k8s.io".into(),
                "v1".into(),
                "clusterrolebindings".into(),
            )),
            Query(CollectionQuery {
                watch: None,
                resource_version: None,
                label_selector: None,
                field_selector: None,
                limit: None,
                continue_token: None,
                send_initial_events: None,
                allow_watch_bookmarks: None,
                timeout_seconds: None,
            }),
            test_user(),
            HeaderMap::new(),
            Bytes::new(),
        )
        .await;

        assert!(
            result.is_err(),
            "delete_collection must propagate a non-NotFound store error — \
             silently returning 200 causes quota drift: client believes all objects \
             deleted, but surviving objects skew quota accounting"
        );
    }

    /// delete_collection_namespaced_resource must propagate a non-NotFound store error
